# MJ-Registry

V1.0 

`index.html`
```
<!DOCTYPE html>
<html lang="bn">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>MJ Ahmad — Registry</title>
<link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{--bg:#F3F5F2;--pan:#FFFFFF;--ink:#16211E;--mut:#5F6E69;--line:#D9DFDB;--pine:#0F4C42;--brass:#B8862B;--ok:#2E7D4F;--warn:#B8862B;--bad:#B3412E;--sel:#E3EEEA;--r:6px}
@media(prefers-color-scheme:dark){:root{--bg:#0F1514;--pan:#161E1C;--ink:#E6ECE9;--mut:#93A29C;--line:#26332F;--pine:#5FB59F;--brass:#D4A74A;--ok:#5DB985;--warn:#D4A74A;--bad:#E1705B;--sel:#1E2D29}}
*{box-sizing:border-box;margin:0}
html,body{height:100%}
body{font-family:"Hind Siliguri","Noto Sans Bengali",system-ui,sans-serif;background:var(--bg);color:var(--ink);display:flex;flex-direction:column;font-size:15px;line-height:1.5}
:focus-visible{outline:2px solid var(--brass);outline-offset:2px}
#splash{position:fixed;inset:0;z-index:99;background:var(--pine);color:#F3F5F2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;cursor:pointer;transition:opacity .5s}
#splash.out{opacity:0;pointer-events:none}
#splash img{width:96px;height:96px;object-fit:contain}
#splash h1{font-size:34px;font-weight:700;letter-spacing:.5px}
#splash p{opacity:.8}
#splash i{display:block;height:2px;width:0;background:var(--brass);animation:bar var(--ms,1.8s) linear forwards}
@keyframes bar{to{width:180px}}
header{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--pine);color:#F3F5F2;flex:none}
header img{width:36px;height:36px;object-fit:contain}
header h1{font-size:18px;font-weight:700;line-height:1.2}
header small{display:block;opacity:.8;font-size:12px}
#q{margin-left:auto;width:min(320px,45%);padding:7px 10px;border-radius:var(--r);border:1px solid #ffffff44;background:#ffffff1c;color:#fff;font:inherit}
#q::placeholder{color:#ffffffaa}
#burger{display:none;background:none;border:0;color:#fff;font-size:22px}
.main{flex:1;display:flex;min-height:0}
nav{width:290px;flex:none;overflow:auto;background:var(--pan);border-right:1px solid var(--line);padding:10px 6px}
nav ul{list-style:none;padding:0}
nav ul ul{margin-left:14px;border-left:1px solid var(--line);padding-left:4px}
.node{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:var(--r);cursor:pointer;user-select:none}
.node:hover{background:var(--sel)}
.node.act{background:var(--sel);color:var(--pine);font-weight:600;box-shadow:inset 3px 0 var(--brass)}
.chev{width:16px;text-align:center;color:var(--mut);transition:transform .15s;flex:none}
.open>.node .chev{transform:rotate(90deg)}
nav li>ul{display:none}nav li.open>ul{display:block}
.ic{width:18px;text-align:center;flex:none}
.lb{flex:1;min-width:0}.lb small{display:block;color:var(--mut);font-size:11.5px;line-height:1.2;font-weight:400}
.cnt{font-size:11.5px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:0 7px;color:var(--mut)}
section#view{flex:1;overflow:auto;padding:20px 24px}
h2{font-size:22px;margin-bottom:2px}.sub{color:var(--mut);margin-bottom:14px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:22px}
.stat{background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:12px;cursor:pointer}
.stat b{font-size:28px;display:block;line-height:1.1}.stat span{color:var(--mut);font-size:13px}
.stat.bad b{color:var(--bad)}
.bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}
.chip{border:1px solid var(--line);background:var(--pan);color:var(--ink);border-radius:16px;padding:2px 12px;font:inherit;font-size:13px;cursor:pointer}
.chip.on{background:var(--pine);color:#fff;border-color:var(--pine)}
.row{display:grid;grid-template-columns:132px 1fr auto;gap:12px;align-items:center;background:var(--pan);border:1px solid var(--line);border-radius:var(--r);padding:9px 12px;margin-bottom:6px;cursor:pointer}
.row:hover{border-color:var(--pine)}
.id{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine)}
.tt small{display:block;color:var(--mut);font-size:12.5px}
.b{display:inline-block;font-size:12px;border-radius:4px;padding:0 7px;border:1px solid var(--line);margin-left:4px;white-space:nowrap}
.b.todo,.b.low,.b.pass{color:var(--ok)}.b.doing,.b.medium,.b.warning{color:var(--warn)}.b.high,.b.urgent,.b.fail{color:var(--bad)}.b.done{color:var(--mut)}
.empty{padding:40px 0;color:var(--mut);text-align:center}
#modal{position:fixed;inset:0;background:#0008;display:none;z-index:50;justify-content:flex-end}
#modal.on{display:flex}
#modal .p{width:min(520px,100%);background:var(--pan);height:100%;overflow:auto;padding:22px}
#modal dl{display:grid;grid-template-columns:110px 1fr;gap:6px 10px;margin:14px 0}
#modal dt{color:var(--mut)}#modal dd{margin:0;word-break:break-word}
#modal .lnk{color:var(--pine);cursor:pointer;text-decoration:underline;font-family:ui-monospace,monospace;font-size:13px;margin-right:8px}
.hist{border-left:2px solid var(--line);padding-left:12px;margin-top:8px;font-size:13px;color:var(--mut)}
.hist div{margin-bottom:6px}
.x{float:right;background:none;border:0;font-size:22px;color:var(--mut);cursor:pointer}
footer{flex:none;padding:8px 16px;background:var(--pan);border-top:1px solid var(--line);color:var(--mut);font-size:12.5px;display:flex;flex-wrap:wrap;gap:6px 18px;justify-content:space-between}
@media(max-width:820px){#burger{display:block}nav{position:fixed;top:56px;bottom:0;left:0;z-index:40;transform:translateX(-100%);transition:transform .2s;width:290px}nav.on{transform:none}.row{grid-template-columns:1fr}section#view{padding:14px}}
.lang{display:flex;border:1px solid #ffffff55;border-radius:var(--r);overflow:hidden;flex:none}
.lang button{background:none;border:0;color:#fff;padding:5px 11px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;opacity:.75}
.lang button+button{border-left:1px solid #ffffff55}
.lang button.on{background:var(--brass);opacity:1}
#splash .tg{font-style:italic;max-width:420px;text-align:center;font-size:13px;opacity:.65;padding:0 20px}
footer{gap:8px;flex-direction:column;align-items:stretch;max-height:45vh;overflow:auto}
footer a{color:var(--pine);text-decoration:none;font-weight:500}footer a:hover{text-decoration:underline}
.fl{display:flex;flex-wrap:wrap;gap:6px 20px}
footer summary{cursor:pointer;color:var(--ink);font-weight:500}
.cm{display:grid;grid-template-columns:200px 1fr;gap:4px 12px;padding:4px 0;border-bottom:1px dashed var(--line)}
.cm code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;color:var(--pine);cursor:pointer;word-break:break-all}
.fq{font-style:italic;color:var(--ink)}
@media(max-width:820px){.cm{grid-template-columns:1fr}#q{width:34%}}
.lg{background:var(--lc,#6B7B76);color:#fff;font-size:12px;font-weight:700;border-radius:4px;padding:1px 8px;letter-spacing:.4px;white-space:nowrap;align-self:flex-start}
.row .lg{margin-left:4px}
.l-html{--lc:#D8552B}.l-json{--lc:#A38F1A}.l-python{--lc:#3776AB}.l-node{--lc:#3F8A36}.l-shell{--lc:#3E8E3E}.l-css{--lc:#2965F1}.l-ts{--lc:#3178C6}.l-react{--lc:#1F8EA8}.l-markdown{--lc:#5B6B8C}.l-sql{--lc:#8A5AA8}
.cc{background:var(--pan);border:1px solid var(--line);border-left:4px solid var(--lc,#6B7B76);border-radius:var(--r);margin-bottom:14px;overflow:hidden}
.cch{display:flex;gap:12px;align-items:flex-start;padding:10px 12px}
.ct{flex:1;min-width:0}.ct small{display:block;color:var(--mut)}
.ca{display:flex;gap:6px}
.ca button,.tg2{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:var(--r);padding:3px 12px;font:inherit;font-size:13px;cursor:pointer}
.ca button:hover,.tg2:hover{border-color:var(--pine);color:var(--pine)}
.tg2{margin:8px 12px 10px}
.cb{display:flex;background:#0F1917;color:#D8E4DF;font:12.5px/1.6 ui-monospace,Menlo,Consolas,monospace;overflow:auto;position:relative;max-height:70vh}
.cb pre{margin:0}.cb .gt{padding:10px 10px 10px 12px;color:#5F7A72;text-align:right;user-select:none;border-right:1px solid #ffffff14;position:sticky;left:0;background:#0F1917}
.cb .cd{padding:10px 14px;flex:1;min-width:0;tab-size:2}
.cc.fade .cb{cursor:pointer;overflow:hidden}.cc.fade .cb::after{content:"";position:absolute;left:0;right:0;bottom:0;height:30px;background:linear-gradient(transparent,#0F1917)}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation-duration:.01s!important}}
</style>
</head>
<body>
<div id="splash"><img id="sl" alt="Logo"><h1 id="st">MJ Ahmad</h1><p id="ss"></p><p id="sq" class="tg"></p><i></i></div>
<header>
  <button id="burger" aria-label="Menu">☰</button>
  <img id="hl" alt="Logo">
  <div><h1 id="ht">MJ Ahmad</h1><small id="hs"></small></div>
  <input id="q" type="search" placeholder="খুঁজুন / Search — ID, শিরোনাম, ট্যাগ…" aria-label="Search">
  <div class="lang" id="lang" role="group" aria-label="Language"><button data-l="en">EN</button><button data-l="bn">BN</button></div>
</header>
<div class="main"><nav id="nav" aria-label="Menu"></nav><section id="view"></section></div>
<footer><div class="fl" id="fl"></div><details id="fd"><summary id="fs"></summary><div id="fc"></div></details><div class="fq" id="fq"></div><div class="fm" id="f2"></div></footer>
<div id="modal"><div class="p" id="mp"></div></div>
<script>
const $=s=>document.querySelector(s),E=(t,c,h)=>{const e=document.createElement(t);if(c)e.className=c;if(h!=null)e.innerHTML=h;return e};
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const UI={
en:{search:'Search — ID, title, tag…',dash:'Dashboard',recent:'Recent',searchT:'Search',all:'All',empty:'Nothing here yet. Add entries with ./run.sh',overdue:'Overdue',history:'History',copy:'copy',openT:'Open tasks',done:'Done',notes:'Notes',audits:'Audits',failed:'Failed audits',t:'tasks',n:'notes',a:'audits',upd:'Updated',cmds:'Quick commands & emergency help',err:'Could not load data.json. Run ./run.sh serve and open http://localhost:8000',menu:'Menu',codes:'CodeCraft',cp:'Copy',cpd:'Copied ✓',dl:'Download',sa:'Show all',co:'Collapse',ln:'lines',
 st:{todo:'To do',doing:'In progress',done:'Done',low:'Low',medium:'Medium',high:'High',urgent:'Urgent',pass:'Pass',warning:'Warning',fail:'Fail'},
 ty:{tasks:'Tasks',notes:'Notes',audits:'Audits',all:'Registry',codes:'CodeCraft'},
 fk:{status:'Status',priority:'Priority',due:'Due',category:'Category',tags:'Tags',created_at:'Created',completed_at:'Completed',desc:'Description',body:'Note',result:'Result',target:'Target',findings:'Findings',auditor:'Auditor',related:'Related',pinned:'Pinned',filename:'File',source:'Source',lang_label:'Type',lines:'Lines',bytes:'Size (bytes)'}},
bn:{search:'খুঁজুন — আইডি, শিরোনাম, ট্যাগ…',dash:'ড্যাশবোর্ড',recent:'সাম্প্রতিক',searchT:'অনুসন্ধান',all:'সব',empty:'এখনো কিছু নেই। ./run.sh দিয়ে যুক্ত করুন',overdue:'মেয়াদোত্তীর্ণ',history:'ইতিহাস',copy:'কপি',openT:'খোলা টাস্ক',done:'সম্পন্ন',notes:'নোট',audits:'অডিট',failed:'ব্যর্থ অডিট',t:'টাস্ক',n:'নোট',a:'অডিট',upd:'আপডেট',cmds:'দ্রুত কমান্ড ও জরুরি নির্দেশনা',err:'data.json লোড হয়নি। ./run.sh serve চালিয়ে http://localhost:8000 খুলুন',menu:'মেনু',codes:'কোডক্রাফ্ট',cp:'কপি',cpd:'কপি হয়েছে ✓',dl:'ডাউনলোড',sa:'সবটুকু দেখুন',co:'গুটিয়ে নিন',ln:'লাইন',
 st:{todo:'করণীয়',doing:'চলমান',done:'সম্পন্ন',low:'নিম্ন',medium:'মাঝারি',high:'উচ্চ',urgent:'জরুরি',pass:'উত্তীর্ণ',warning:'সতর্কতা',fail:'ব্যর্থ'},
 ty:{tasks:'টাস্ক',notes:'নোট',audits:'অডিট',all:'রেজিস্ট্রি',codes:'কোডক্রাফ্ট'},
 fk:{status:'অবস্থা',priority:'অগ্রাধিকার',due:'শেষ তারিখ',category:'বিভাগ',tags:'ট্যাগ',created_at:'তৈরি',completed_at:'সম্পন্ন হয়েছে',desc:'বিবরণ',body:'নোট',result:'ফলাফল',target:'লক্ষ্য',findings:'পর্যবেক্ষণ',auditor:'অডিটর',related:'সম্পর্কিত',pinned:'পিন করা',filename:'ফাইল',source:'উৎস',lang_label:'ধরন',lines:'লাইন',bytes:'আকার (বাইট)'}}};
let D,lang='en',cur={type:'dashboard'},curId='dash',open=new Set(),sf='',search='',mId='';
try{const s=localStorage.getItem('mj_lang');if(s==='bn'||s==='en')lang=s}catch(e){}
const T=()=>UI[lang],pick=(en,bn)=>lang==='bn'?(bn||en):(en||bn),lab=n=>pick(n.en,n.bn),ttl=i=>pick(i.title,i.title_bn);
const items=t=>t==='all'?[...D.tasks.map(x=>({...x,_k:'tasks'})),...D.notes.map(x=>({...x,_k:'notes'})),...D.audits.map(x=>({...x,_k:'audits'})),...(D.codes||[]).map(x=>({...x,_k:'codes',menu_path:x.menu_path||['codecraft','c-'+x.lang]}))]:(D[t]||[]).map(x=>({...x,_k:t}));
const match=(it,f)=>!f||Object.entries(f).every(([k,v])=>Array.isArray(it[k])?it[k].includes(v):it[k]===v);
const cnt=v=>v&&v.type!=='dashboard'?items(v.type).filter(i=>match(i,v.filter)).length:null;
const fmt=s=>s?new Date(s).toLocaleString(lang==='bn'?'bn-BD':'en-GB',{dateStyle:'medium',timeStyle:'short'}):'—';
const overdue=t=>t.status!=='done'&&t.due&&t.due<new Date().toISOString().slice(0,10);

fetch('data.json?'+Date.now()).then(r=>r.json()).then(init).catch(e=>{$('#view').innerHTML='<div class="empty">'+esc(T().err)+'<br><small>'+esc(e)+'</small></div>';hideSplash()});

function init(d){
  D=d;const m=d.meta;
  $('#hl').src=$('#sl').src=m.logo;
  (function pre(ns){ns.forEach(n=>{if(n.open)open.add(n.id);pre(n.children||[])})})(D.menu);
  $('#splash').style.setProperty('--ms',(m.splash_ms||1800)+'ms');
  document.querySelectorAll('#lang button').forEach(b=>b.onclick=()=>{lang=b.dataset.l;try{localStorage.setItem('mj_lang',lang)}catch(e){}applyLang()});
  applyLang();
  if(location.hash.length>1)showM(location.hash.slice(1));
  setTimeout(hideSplash,m.splash_ms||1800);
}
function applyLang(){
  const m=D.meta,t=T(),sub=pick(m.subtitle_en,m.subtitle_bn);
  document.documentElement.lang=lang;document.title=m.title+' — '+sub;
  $('#ht').textContent=$('#st').textContent=m.title;$('#hs').textContent=$('#ss').textContent=sub;
  $('#sq').textContent=m.tagline||'';$('#q').placeholder=t.search;
  document.querySelectorAll('#lang button').forEach(b=>b.classList.toggle('on',b.dataset.l===lang));
  drawNav();drawFooter();render();if($('#modal').classList.contains('on'))showM(mId)}
function hideSplash(){$('#splash').classList.add('out')}
$('#splash').onclick=hideSplash;
$('#burger').onclick=()=>$('#nav').classList.toggle('on');
$('#q').oninput=e=>{search=e.target.value.trim().toLowerCase();render()};
$('#modal').onclick=e=>{if(e.target.id==='modal')closeM()};
addEventListener('keydown',e=>{if(e.key==='Escape')closeM()});

function drawFooter(){
  const m=D.meta,t=T();
  $('#fl').innerHTML=(m.links||[]).map(l=>`<a href="${esc(l.url)}"${l.url.startsWith('mailto:')?'':' target="_blank" rel="noopener"'}><span>${esc(l.icon||'')}</span> ${esc(pick(l.en,l.bn))}</a>`).join('');
  const c=m.commands||[];$('#fd').hidden=!c.length;$('#fs').textContent=t.cmds;
  $('#fc').innerHTML=c.map(x=>`<div class="cm"><span>${esc(pick(x.en,x.bn))}</span><code title="click to copy">${esc(x.cmd)}</code></div>`).join('');
  $('#fc').querySelectorAll('code').forEach(e=>e.onclick=()=>navigator.clipboard&&navigator.clipboard.writeText(e.textContent));
  $('#fq').textContent=m.tagline?'“'+m.tagline+'”':'';
  $('#f2').textContent=`${pick(m.footer_en,m.footer_bn)} · v${m.version} · ${D.tasks.length} ${t.t} · ${D.notes.length} ${t.n} · ${D.audits.length} ${t.a} · ${(D.codes||[]).length} ${t.codes} · ${t.upd} ${fmt(m.updated_at)} · © ${new Date().getFullYear()} ${m.title}`}

function drawNav(){const nav=$('#nav');nav.innerHTML='';nav.append(tree(D.menu))}
function tree(ns){
  const ul=E('ul');
  ns.forEach(n=>{
    const li=E('li',open.has(n.id)?'open':''),kids=n.children&&n.children.length,c=cnt(n.view);
    const row=E('div','node'+(n.id===curId?' act':''));
    row.innerHTML=`<span class="chev">${kids?'›':''}</span><span class="ic">${n.icon||''}</span><span class="lb">${esc(lab(n))}</span>${c!=null?`<span class="cnt">${c}</span>`:''}`;
    row.tabIndex=0;
    const go=()=>{if(kids){open.has(n.id)?open.delete(n.id):open.add(n.id)}if(n.view){cur=n.view;curId=n.id;sf='';$('#nav').classList.remove('on')}drawNav();render()};
    row.onclick=go;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}};
    li.append(row);if(kids)li.append(tree(n.children));ul.append(li)});
  return ul}

function render(){
  const v=$('#view');v.innerHTML='';
  if(search){list(v,'all',null,true);return}
  cur.type==='dashboard'?dash(v):list(v,cur.type,cur.filter)}

function dash(v){
  const t=T(),TK=D.tasks,A=D.audits;
  v.innerHTML=`<h2>${t.dash}</h2>`;
  const g=E('div','grid');
  [[t.openT,TK.filter(x=>x.status!=='done').length,'tasks',{}],[t.done,TK.filter(x=>x.status==='done').length,'tasks',{status:'done'}],[t.overdue,TK.filter(overdue).length,'tasks',{},'bad'],[t.notes,D.notes.length,'notes',{}],[t.audits,A.length,'audits',{}],[t.failed,A.filter(a=>a.result==='fail').length,'audits',{result:'fail'},'bad'],[t.codes,(D.codes||[]).length,'codes',{}]]
   .forEach(([l,n,ty,f,c])=>{const s=E('div','stat '+(c||''),`<b>${n}</b><span>${l}</span>`);s.onclick=()=>{cur={type:ty,filter:f};curId='';drawNav();render()};g.append(s)});
  v.append(g,E('h2','',t.recent));
  items('all').sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,8).forEach(i=>v.append(row(i)))}

function list(v,type,filter,isSearch){
  const t=T();
  const nm=isSearch?null:nodeMap()[curId];
  v.append(E('h2','',isSearch?t.searchT:(nm&&nm.view&&nm.view.type===type?lab(nm):t.ty[type])));
  if(nm&&nm.view&&nm.view.filter&&nm.view.filter.menu_path)v.append(E('div','sub','📁 '+esc(crumb(pathOf(nm.view.filter.menu_path)))));
  if(nm&&nm.children&&nm.children.length){const b=E('div','bar');nm.children.forEach(c=>{const n=cnt(c.view),ch=E('button','chip',esc(lab(c))+(n!=null?` (${n})`:''));ch.onclick=()=>{open.add(nm.id);if(c.view){cur=c.view;curId=c.id;sf=''}drawNav();render()};b.append(ch)});v.append(b)}
  if(isSearch)v.append(E('div','sub','“'+esc(search)+'”'));
  let arr=items(type).filter(i=>match(i,filter)).filter(i=>!search||[i.id,i.title,i.title_bn,i.desc,i.body,i.findings,i.desc_bn,i.filename,i.content,i.category,(i.tags||[]).join(' ')].join(' ').toLowerCase().includes(search));
  const sts=[...new Set(arr.map(i=>i.status||i.result).filter(Boolean))];
  if(sts.length>1){const b=E('div','bar');['',...sts].forEach(s=>{const c=E('button','chip'+(sf===s?' on':''),s?t.st[s]||s:t.all);c.onclick=()=>{sf=s;render()};b.append(c)});v.append(b)}
