">${t.overdue}</span>`:''}${i.pinned?'<span class=\\\"b\\\">📌</span>':''}${i.lang_label?`<span class=\\\"lg l-${esc(i.lang)}\\\">${esc(i.lang_label)}</span>`:''}</span>`;\\n  r.onclick=()=>showM(i.id);return r}\\n\\nfunction showM(id){\\n  const it=items('all').find(x=>x.id===id);if(!it)return;mId=id;\\n  const t=T(),skip=['history','title','title_bn','_k','id','content','sha256','lang','ext','desc_bn','menu_path'],p=$('#mp');\\n  const val=(k,v)=>k==='desc'?esc(pick(v,it.desc_bn)):Array.isArray(v)?(k==='related'?v.map(x=>`<span class=\\\"lnk\\\" data-id=\\\"${esc(x)}\\\">${esc(x)}</span>`).join(''):esc(v.join(', '))):k.endsWith('_at')||k==='due'?fmt(v):k==='status'||k==='priority'||k==='result'?esc(t.st[v]||v):esc(v===true?'✔':v);\\n  p.innerHTML=`<button class=\\\"x\\\" aria-label=\\\"Close\\\">×</button><div class=\\\"id\\\">${esc(it.id)} <a class=\\\"lnk\\\" href=\\\"#${esc(it.id)}\\\" style=\\\"font-size:12px\\\" onclick=\\\"navigator.clipboard&&navigator.clipboard.writeText('${esc(it.id)}')\\\">${t.copy}</a></div><h2>${esc(ttl(it))}</h2><dl>${Object.entries(it).filter(([k,v])=>!skip.includes(k)&&v!==''&&!(Array.isArray(v)&&!v.length)).map(([k,v])=>`<dt>${esc(t.fk[k]||k)}</dt><dd>${val(k,v)}</dd>`).join('')}</dl><h2 style=\\\"font-size:16px\\\">${t.history}</h2><div class=\\\"hist\\\">${(it.history||[]).map(h=>`<div>${fmt(h.at)} — ${esc(h.event)}${h.note?': '+esc(h.note):''}</div>`).join('')}</div>`;\\n  p.style.width=it._k==='codes'?'min(900px,100%)':'';if(it._k==='codes')p.querySelector('h2').after(codeCard(it,true));p.querySelector('.x').onclick=closeM;p.querySelectorAll('[data-id]').forEach(e=>e.onclick=()=>showM(e.dataset.id));\\n  $('#modal').classList.add('on');location.hash=id}\\nfunction closeM(){$('#modal').classList.remove('on');history.replaceState(null,'',location.pathname)}\\naddEventListener('hashchange',()=>{if(D&&location.hash.length>1)showM(location.hash.slice(1))});\\n</script>\\n</body>\\n</html>\\n```\\n\\n---\\n\\n`add_code.py`\\n```\\n#!/usr/bin/env python3\\n\\\"\\\"\\\"Save a whole file (local path or http/https URL) into CodeCraft.\\n\\npython3 add_code.py ~/mj/portal/index.html \\\"Title\\\" \\\"Description\\\" --bn \\\"শিরোনাম\\\" --bn \\\"বর্ণনা\\\"\\n  (1st --bn = title BN, 2nd --bn = description BN; or --title-bn / --desc-bn)\\n\\nWhere it goes (see the tree with:  ./run.sh menu):\\n  (nothing)                        -> CodeCraft > <file type>        e.g. CodeCraft > HTML\\n  --menu \\\"CodeCraft/Web/Portal\\\"    -> into an existing menu/submenu (menu id or name path)\\n  --new-menu \\\"UI/Forms\\\"            -> create nested submenus (under --menu, or CodeCraft) and put it there\\n  --new-menu-bn \\\"ইউআই/ফর্ম\\\"        -> Bangla names for the new submenus, same order\\nOther: --category X --tags a,b --lang python --force.  No arguments = interactive.\\\"\\\"\\\"\\nimport argparse, os, urllib.request\\nfrom urllib.parse import urlparse\\nfrom _lib import *\\nMAX = 2 * 1024 * 1024\\na = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\\na.add_argument(\\\"source\\\", nargs=\\\"?\\\", default=\\\"\\\"); a.add_argument(\\\"title\\\", nargs=\\\"?\\\", default=\\\"\\\"); a.add_argument(\\\"desc\\\", nargs=\\\"?\\\", default=\\\"\\\")\\na.add_argument(\\\"--bn\\\", action=\\\"append\\\", default=[]); a.add_argument(\\\"--title-bn\\\", default=\\\"\\\"); a.add_argument(\\\"--desc-bn\\\", default=\\\"\\\")\\na.add_argument(\\\"--menu\\\", default=\\\"\\\"); a.add_argument(\\\"--new-menu\\\", default=\\\"\\\"); a.add_argument(\\\"--new-menu-bn\\\", default=\\\"\\\")\\na.add_argument(\\\"--category\\\", default=\\\"general\\\"); a.add_argument(\\\"--tags\\\", default=\\\"\\\"); a.add_argument(\\\"--lang\\\", default=\\\"\\\"); a.add_argument(\\\"--force\\\", action=\\\"store_true\\\")\\nx = a.parse_intermixed_args()\\nif not x.source:\\n    print(\\\"— New CodeCraft entry (Enter to skip optional fields) —\\\")\\n    x.source = ask(\\\"File path or URL *\\\", req=True); x.title = ask(\\\"Title (EN)\\\"); x.title_bn = ask(\\\"শিরোনাম (BN)\\\")\\n    x.desc = ask(\\\"Description (EN)\\\"); x.desc_bn = ask(\\\"বর্ণনা (BN)\\\")\\n    x.menu = ask(\\\"Existing menu (id or path, Enter = by file type; ./run.sh menu shows the tree)\\\")\\n    x.new_menu = ask(\\\"New submenu name(s) e.g. UI/Forms (optional)\\\"); x.new_menu_bn = ask(\\\"নতুন সাবমেনুর বাংলা নাম (optional)\\\") if x.new_menu else \\\"\\\"\\n    x.category = ask(\\\"Category\\\", \\\"general\\\"); x.tags = ask(\\\"Tags a,b\\\")\\ntb = x.title_bn or (x.bn[0] if x.bn else \\\"\\\"); db = x.desc_bn or (x.bn[1] if len(x.bn) > 1 else \\\"\\\")\\nsrc = x.source\\ntry:\\n    if src.startswith((\\\"http://\\\", \\\"https://\\\")):\\n        with urllib.request.urlopen(urllib.request.Request(src, headers={\\\"User-Agent\\\": \\\"mj-registry\\\"}), timeout=20) as r: raw = r.read(MAX + 1)\\n        name = os.path.basename(urlparse(src).path) or \\\"index.html\\\"\\n    else:\\n        p = os.path.abspath(os.path.expanduser(src))\\n        if not os.path.isfile(p): die(f\\\"file not found: {src}\\\")\\n        with open(p, \\\"rb\\\") as f: raw = f.read(MAX + 1)\\n        name = os.path.basename(p)\\nexcept Exception as e: die(f\\\"could not read {src}: {e}\\\")\\nif len(raw) > MAX: die(\\\"file larger than 2 MB\\\")\\ntry: text = raw.decode(\\\"utf-8-sig\\\").replace(\\\"\\\\r\\\\n\\\", \\\"\\\\n\\\")\\nexcept UnicodeDecodeError: die(\\\"not a UTF-8 text file (binary files are not supported)\\\")\\nlang, label = detect(name, text, x.lang.lower())\\nsha = hashlib.sha256(text.encode(\\\"utf-8\\\")).hexdigest()\\nd = normalize(load()); root = ensure_root(d)\\ndup = next((c for c in d[\\\"codes\\\"] if c.get(\\\"sha256\\\") == sha), None)\\nif dup and not x.force: die(f\\\"identical content already saved as {dup['id']} (use --force to add anyway)\\\")\\nnode, path = root, [\\\"codecraft\\\"]\\nif x.menu:\\n    node, path = find_node(d, x.menu)\\n    if not node: die(f\\\"menu not found: {x.menu}  (run ./run.sh menu to see the tree, or create it with --new-menu)\\\")\\nif x.new_menu:\\n    node, path = ensure_chain(d, node, path, [s.strip() for s in x.new_menu.split(\\\"/\\\") if s.strip()], x.new_menu_bn.split(\\\"/\\\"))\\nelif not x.menu:\\n    node, path = ensure_chain(d, root, [\\\"codecraft\\\"], [label])\\ni = next_id(d, \\\"code\\\")\\nd[\\\"codes\\\"].append({\\\"id\\\": i, \\\"title\\\": x.title or name, \\\"title_bn\\\": tb, \\\"desc\\\": x.desc, \\\"desc_bn\\\": db, \\\"filename\\\": name,\\n  \\\"source\\\": src, \\\"lang\\\": lang, \\\"lang_label\\\": label, \\\"ext\\\": name.rsplit(\\\".\\\", 1)[-1].lower() if \\\".\\\" in name else \\\"\\\",\\n  \\\"lines\\\": text.count(\\\"\\\\n\\\") + (0 if text == \\\"\\\" or text.endswith(\\\"\\\\n\\\") else 1), \\\"bytes\\\": len(raw), \\\"sha256\\\": sha,\\n  \\\"menu_path\\\": path, \\\"category\\\": x.category, \\\"tags\\\": tags(x.tags), \\\"created_at\\\": now(),\\n  \\\"history\\\": [{\\\"at\\\": now(), \\\"event\\\": \\\"created\\\", \\\"note\\\": src}], \\\"content\\\": text})\\nsave(d); print(f\\\"✔ CodeCraft added: {i}  [{label}]  {name}  →  \\\" + \\\" › \\\".join(next(n for n, p in walk(d['menu']) if n['id'] == k)['en'] for k in path))\\n```\\n\\n---\\n\\n`_lib.py`\\n```\\n#!/usr/bin/env python3\\n\\\"\\\"\\\"Shared helpers: load/save data.json safely, unique IDs, history log.\\\"\\\"\\\"\\nimport json, os, shutil, sys\\nfrom datetime import datetime\\nHERE = os.path.dirname(os.path.abspath(__file__))\\nDATA = os.path.join(HERE, \\\"data.json\\\")\\nKIND = {\\\"task\\\": (\\\"TSK\\\", \\\"tasks\\\"), \\\"note\\\": (\\\"NOT\\\", \\\"notes\\\"), \\\"audit\\\": (\\\"AUD\\\", \\\"audits\\\"), \\\"code\\\": (\\\"CDE\\\", \\\"codes\\\")}\\n\\ndef now(): return datetime.now().astimezone().isoformat(timespec=\\\"seconds\\\")\\n\\ndef load():\\n    with open(DATA, encoding=\\\"utf-8\\\") as f: d = json.load(f)\\n    d.setdefault(\\\"codes\\\", []); return d\\n\\ndef save(d):\\n    d[\\\"meta\\\"][\\\"updated_at\\\"] = now()\\n    if os.path.exists(DATA): shutil.copy(DATA, DATA + \\\".bak\\\")\\n    tmp = DATA + \\\".tmp\\\"\\n    with open(tmp, \\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n        json.dump(d, f, ensure_ascii=False, indent=2)\\n    os.replace(tmp, DATA)\\n\\ndef next_id(d, kind):\\n    \\\"\\\"\\\"Never reuses an ID: PREFIX-YYYY-NNNN, counter kept per kind & year.\\\"\\\"\\\"\\n    p, _ = KIND[kind]; y = datetime.now().year\\n    c = d[\\\"meta\\\"].setdefault(\\\"counters\\\", {}).setdefault(kind, {})\\n    c[str(y)] = c.get(str(y), 0) + 1\\n    return f\\\"{p}-{y}-{c[str(y)]:04d}\\\"\\n\\ndef find(d, id_):\\n    for k, (p, key) in KIND.items():\\n        for it in d[key]:\\n            if it[\\\"id\\\"] == id_: return k, it\\n    return None, None\\n\\ndef tags(s): return [t.strip() for t in (s or \\\"\\\").split(\\\",\\\") if t.strip()]\\n\\ndef die(msg): print(\\\"ERROR:\\\", msg, file=sys.stderr); sys.exit(1)\\n\\ndef ask(label, default=\\\"\\\", req=False, choices=None):\\n    \\\"\\\"\\\"Interactive prompt used when a script runs without arguments.\\\"\\\"\\\"\\n    while True:\\n        v = input(f\\\"{label}{' ['+default+']' if default else ''}: \\\").strip() or default\\n        if req and not v: print(\\\"  required\\\"); continue\\n        if choices and v not in choices: print(\\\"  choose:\\\", \\\"/\\\".join(choices)); continue\\n        return v\\n\\nimport hashlib\\nEXT = {\\\"html\\\":(\\\"html\\\",\\\"HTML\\\"),\\\"htm\\\":(\\\"html\\\",\\\"HTML\\\"),\\\"json\\\":(\\\"json\\\",\\\"JSON\\\"),\\\"py\\\":(\\\"python\\\",\\\"Python\\\"),\\n \\\"js\\\":(\\\"node\\\",\\\"Node.js\\\"),\\\"mjs\\\":(\\\"node\\\",\\\"Node.js\\\"),\\\"cjs\\\":(\\\"node\\\",\\\"Node.js\\\"),\\\"ts\\\":(\\\"ts\\\",\\\"TypeScript\\\"),\\n \\\"jsx\\\":(\\\"react\\\",\\\"React\\\"),\\\"tsx\\\":(\\\"react\\\",\\\"React\\\"),\\\"sh\\\":(\\\"shell\\\",\\\"Shell\\\"),\\\"bash\\\":(\\\"shell\\\",\\\"Shell\\\"),\\n \\\"css\\\":(\\\"css\\\",\\\"CSS\\\"),\\\"md\\\":(\\\"markdown\\\",\\\"Markdown\\\"),\\\"yml\\\":(\\\"yaml\\\",\\\"YAML\\\"),\\\"yaml\\\":(\\\"yaml\\\",\\\"YAML\\\"),\\n \\\"sql\\\":(\\\"sql\\\",\\\"SQL\\\"),\\\"xml\\\":(\\\"xml\\\",\\\"XML\\\"),\\\"php\\\":(\\\"php\\\",\\\"PHP\\\"),\\\"java\\\":(\\\"java\\\",\\\"Java\\\"),\\\"c\\\":(\\\"c\\\",\\\"C\\\"),\\n \\\"cpp\\\":(\\\"cpp\\\",\\\"C++\\\"),\\\"go\\\":(\\\"go\\\",\\\"Go\\\"),\\\"rs\\\":(\\\"rust\\\",\\\"Rust\\\"),\\\"txt\\\":(\\\"text\\\",\\\"Text\\\")}\\nSHEBANG = {\\\"python\\\":(\\\"python\\\",\\\"Python\\\"),\\\"node\\\":(\\\"node\\\",\\\"Node.js\\\"),\\\"bash\\\":(\\\"shell\\\",\\\"Shell\\\"),\\\"sh\\\":(\\\"shell\\\",\\\"Shell\\\")}\\n\\ndef detect(name, text, force=\\\"\\\"):\\n    if force:\\n        return next((v for v in EXT.values() if v[0] == force), (force, force.upper()))\\n    ext = name.rsplit(\\\".\\\", 1)[-1].lower() if \\\".\\\" in name else \\\"\\\"\\n    if ext in EXT: return EXT[ext]\\n    if text.startswith(\\\"#!\\\"):\\n        for k, v in SHEBANG.items():\\n            if k in text.split(\\\"\\\\n\\\", 1)[0]: return v\\n    return (\\\"text\\\", \\\"Text\\\")\\n\\nimport re\\ndef walk(ns, path=()):\\n    for n in ns:\\n        yield n, path + (n[\\\"id\\\"],)\\n        yield from walk(n.get(\\\"children\\\", []), path + (n[\\\"id\\\"],))\\n\\ndef find_node(d, ref):\\n    \\\"\\\"\\\"ref = menu id, or a label path like 'CodeCraft/Web/Portal' (EN/BN/id, case-insensitive). -> (node, [id path]) or (None, None)\\\"\\\"\\\"\\n    ref = ref.strip()\\n    for n, p in walk(d[\\\"menu\\\"]):\\n        if n[\\\"id\\\"] == ref: return n, list(p)\\n    segs = [s.strip().lower() for s in ref.strip(\\\"/\\\").split(\\\"/\\\") if s.strip()]\\n    if not segs: return None, None\\n    def go(ns, sg, path):\\n        for n in ns:\\n            if sg[0] in (n[\\\"id\\\"].lower(), (n.get(\\\"en\\\") or \\\"\\\").lower(), (n.get(\\\"bn\\\") or \\\"\\\").lower()):\\n                if len(sg) == 1: return n, path + [n[\\\"id\\\"]]\\n                r = go(n.get(\\\"children\\\", []), sg[1:], path + [n[\\\"id\\\"]])\\n                if r[0]: return r\\n        return None, None\\n    r = go(d[\\\"menu\\\"], segs, [])\\n    if r[0]: return r\\n    root = next((n for n in d[\\\"menu\\\"] if n[\\\"id\\\"] == \\\"codecraft\\\"), None)   # 'Web/Portal' means CodeCraft/Web/Portal\\n    return go(root.get(\\\"children\\\", []), segs, [\\\"codecraft\\\"]) if root else (None, None)\\n\\ndef ensure_root(d):\\n    root = next((n for n in d[\\\"menu\\\"] if n[\\\"id\\\"] == \\\"codecraft\\\"), None)\\n    if not root:\\n        root = {\\\"id\\\": \\\"codecraft\\\", \\\"bn\\\": \\\"কোডক্রাফ্ট\\\", \\\"en\\\": \\\"CodeCraft\\\", \\\"icon\\\": \\\"❮❯\\\", \\\"open\\\": True, \\\"view\\\": {\\\"type\\\": \\\"codes\\\"}, \\\"children\\\": []}\\n        k = next((j for j, n in enumerate(d[\\\"menu\\\"]) if n[\\\"id\\\"] == \\\"registry\\\"), len(d[\\\"menu\\\"])); d[\\\"menu\\\"].insert(k, root)\\n    root.setdefault(\\\"children\\\", []); return root\\n\\ndef ensure_chain(d, parent, ppath, names, bns=()):\\n    \\\"\\\"\\\"Create (or reuse, matched by name) nested submenus under parent. -> (deepest node, id path)\\\"\\\"\\\"\\n    ids = {n[\\\"id\\\"] for n, _ in walk(d[\\\"menu\\\"])}\\n    for k, name in enumerate(names):\\n        sib = parent.setdefault(\\\"children\\\", [])\\n        hit = next((c for c in sib if name.lower() in ((c.get(\\\"en\\\") or \\\"\\\").lower(), (c.get(\\\"bn\\\") or \\\"\\\").lower())), None)\\n        if not hit:\\n            bn = bns[k].strip() if k < len(bns) and bns[k].strip() else name\\n            base = \\\"c-\\\" + (re.sub(r\\\"[^a-z0-9]+\\\", \\\"-\\\", name.lower()).strip(\\\"-\\\") or \\\"m\\\"); nid = base; i = 2\\n            while nid in ids: nid = f\\\"{base}-{i}\\\"; i += 1\\n            ids.add(nid)\\n            hit = {\\\"id\\\": nid, \\\"bn\\\": bn, \\\"en\\\": name, \\\"view\\\": {\\\"type\\\": \\\"codes\\\", \\\"filter\\\": {\\\"menu_path\\\": nid}}}\\n            sib.append(hit)\\n        parent = hit; ppath = ppath + [hit[\\\"id\\\"]]\\n    return parent, ppath\\n\\ndef normalize(d):\\n    \\\"\\\"\\\"Upgrade older data: language nodes filter by menu_path; entries get a menu_path.\\\"\\\"\\\"\\n    root = ensure_root(d)\\n    for c in root[\\\"children\\\"]:\\n        f = c.get(\\\"view\\\", {}).get(\\\"filter\\\", {})\\n        if \\\"lang\\\" in f: c[\\\"view\\\"][\\\"filter\\\"] = {\\\"menu_path\\\": c[\\\"id\\\"]}\\n    for it in d[\\\"codes\\\"]:\\n        it.setdefault(\\\"menu_path\\\", [\\\"codecraft\\\", \\\"c-\\\" + it[\\\"lang\\\"]])\\n    return d\\n```\\n\\n---\\n\\n`validate.py`\\n```\\n#!/usr/bin/env python3\\n\\\"\\\"\\\"Checks data.json integrity. Exit 0 = OK, 1 = problems.\\\"\\\"\\\"\\nimport re\\nfrom _lib import *\\nd = load(); errs = []; seen = set()\\nreq = {\\\"task\\\": [\\\"id\\\", \\\"title\\\", \\\"status\\\", \\\"priority\\\", \\\"created_at\\\"], \\\"note\\\": [\\\"id\\\", \\\"title\\\", \\\"created_at\\\"],\\n       \\\"audit\\\": [\\\"id\\\", \\\"title\\\", \\\"result\\\", \\\"created_at\\\"],\\n       \\\"code\\\": [\\\"id\\\", \\\"title\\\", \\\"lang\\\", \\\"content\\\", \\\"created_at\\\"]}\\nfor k, (p, key) in KIND.items():\\n    for it in d.get(key, []):\\n        i = it.get(\\\"id\\\", \\\"?\\\")\\n        if i in seen: errs.append(f\\\"duplicate ID {i}\\\")\\n        seen.add(i)\\n        if not re.fullmatch(rf\\\"{p}-\\\\d{{4}}-\\\\d{{4,}}\\\", i): errs.append(f\\\"bad ID format {i}\\\")\\n        errs += [f\\\"{i}: missing '{f}'\\\" for f in req[k] if not it.get(f)]\\n        if k == \\\"code\\\" and it.get(\\\"content\\\") and hashlib.sha256(it[\\\"content\\\"].encode(\\\"utf-8\\\")).hexdigest() != it.get(\\\"sha256\\\"): errs.append(f\\\"{i}: content hash mismatch\\\")\\n        c = d[\\\"meta\\\"].get(\\\"counters\\\", {}).get(k, {}).get(i.split(\\\"-\\\")[1], 0)\\n        if i[:3] == p and int(i.split(\\\"-\\\")[2]) > c: errs.append(f\\\"{i}: counter behind ({c})\\\")\\nfor key in (\\\"tasks\\\", \\\"notes\\\", \\\"audits\\\", \\\"codes\\\"):\\n    for it in d.get(key, []):\\n        for r in it.get(\\\"related\\\", []):\\n            if r not in seen: errs.append(f\\\"{it['id']}: related ID missing {r}\\\")\\nmids = []\\ndef walk(ns):\\n    for n in ns:\\n        mids.append(n.get(\\\"id\\\")); \\n        if not n.get(\\\"id\\\") or not (n.get(\\\"bn\\\") or n.get(\\\"en\\\")): errs.append(f\\\"menu node needs id+label: {n}\\\")\\n        walk(n.get(\\\"children\\\", []))\\nwalk(d.get(\\\"menu\\\", []))\\nfor it in d.get('codes', []):\\n    errs += [f\\\"{it['id']}: menu_path id not in menu: {m}\\\" for m in it.get('menu_path', []) if m not in mids]\\nerrs += [f\\\"duplicate menu id {m}\\\" for m in set(mids) if mids.count(m) > 1]\\nif errs: print(\\\"✘ Problems:\\\"); [print(\\\"  -\\\", e) for e in errs]; sys.exit(1)\\nprint(f\\\"✔ OK — {len(d['tasks'])} tasks, {len(d['notes'])} notes, {len(d['audits'])} audits, {len(d['codes'])} codes, {len(mids)} menu nodes\\\")\\n```\\n\\n---\\n\\n`run.sh`\\n```\\n#!/usr/bin/env bash\\n# ./run.sh task|note|audit|code|menu|done|check|serve [args...]\\ncd \\\"$(dirname \\\"$0\\\")\\\"\\nc=\\\"$1\\\"; shift\\ncase \\\"$c\\\" in\\n  task) python3 add_task.py \\\"$@\\\" && python3 validate.py ;;\\n  note) python3 add_note.py \\\"$@\\\" && python3 validate.py ;;\\n  audit) python3 add_audit.py \\\"$@\\\" && python3 validate.py ;;\\n  done) python3 complete_task.py \\\"$@\\\" && python3 validate.py ;;\\n  code) python3 add_code.py \\\"$@\\\" && python3 validate.py ;;\\n  menu) python3 menu.py \\\"$@\\\" && python3 validate.py ;;\\n  check) python3 validate.py ;;\\n  serve) echo \\\"Open http://localhost:8000\\\"; python3 -m http.server 8000 ;;\\n  *) echo \\\"usage: ./run.sh task|note|audit|code|menu|done|check|serve ...\\\" ;;\\nesac\\n```\\n\\n---\\n\\n`data.json`\\n```\\n{\\n  \\\"meta\\\": {\\n    \\\"title\\\": \\\"MJ Ahmad\\\",\\n    \\\"subtitle_bn\\\": \\\"টাস্ক · নোট · অডিট রেজিস্ট্রি\\