/* css/style.css
   Clean, responsive stylesheet for Quraner Fariwala demo
   Matches HTML structure and JS expectations (cart modal, toast, forms)
*/

/* -------------------------
   Theme variables
   ------------------------- */
:root{
  --page-bg: #faf9f7;
  --panel-bg: #ffffff;
  --muted: #6b7280;
  --primary: #0ea5a4;
  --accent: #06b6d4;
  --fg-dark: #042028;
  --card-border: rgba(2,6,23,0.06);
  --container-max: 1100px;
  --radius: 10px;
  --shadow-soft: 0 6px 18px rgba(2,6,23,0.04);
  --shadow-card: 0 8px 30px rgba(2,6,23,0.04);
  --gap: 1rem;
  --transition: 180ms ease;
  --text-small: 0.875rem;
}

/* -------------------------
   Base layout
   ------------------------- */
* { box-sizing: border-box; }
html,body{ height:100%; margin:0; background:var(--page-bg); color:var(--fg-dark); font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial; -webkit-font-smoothing:antialiased; -moz-osx-font-smoothing:grayscale; }
.container{ max-width:var(--container-max); margin:0 auto; padding:1.25rem; }

/* Typography */
h1{ font-size:1.75rem; margin:0 0 0.5rem 0; line-height:1.05; }
h2{ font-size:1.25rem; margin:0 0 0.5rem 0; }
.lead{ color:var(--muted); margin:0 0 1rem 0; }
.small{ font-size:var(--text-small); color:var(--muted); }

/* -------------------------
   Header / Nav
   ------------------------- */
header{ background:var(--panel-bg); border-bottom:1px solid var(--card-border); box-shadow:var(--shadow-soft); position:sticky; top:0; z-index:60; }
.nav{ display:flex; align-items:center; justify-content:space-between; gap:var(--gap); padding:0.8rem 1rem; max-width:var(--container-max); margin:0 auto; }
.brand{ display:flex; align-items:center; gap:0.75rem; text-decoration:none; color:var(--fg-dark); }
.logo{ width:48px; height:48px; border-radius:10px; display:inline-flex; align-items:center; justify-content:center; font-weight:800; background:linear-gradient(135deg,var(--primary),var(--accent)); color:#fff; box-shadow:var(--shadow-soft); object-fit:cover; }
.brand-title{ font-weight:800; font-size:1rem; line-height:1; display:flex; gap:0.25rem; align-items:center; }
.brand-sub{ font-size:0.85rem; color:var(--muted); margin-top:2px; }

/* Nav links */
.nav-links{ display:flex; gap:0.6rem; align-items:center; }
.nav-link{ padding:0.45rem 0.8rem; border-radius:8px; color:var(--fg-dark); font-weight:700; text-decoration:none; }
.nav-link:hover{ background: rgba(2,6,23,0.02); }

/* Header cart */
.header-cart{ display:flex; align-items:center; gap:0.5rem; padding:0.35rem 0.6rem; border-radius:8px; cursor:pointer; background:transparent; color:var(--fg-dark); }
.cart-count{ background:var(--primary); color:#fff; padding:0.12rem 0.45rem; border-radius:999px; font-weight:800; font-size:0.85rem; }

/* Mobile toggle */
#mobile-toggle{ display:none; background:transparent; border:0; font-size:1.25rem; cursor:pointer; color:var(--fg-dark); }

/* -------------------------
   Hero
   ------------------------- */
.hero{ padding:2rem 0; display:flex; align-items:center; gap:1.25rem; }
.kicker{ display:inline-block; color:var(--primary); background: rgba(14,165,164,0.06); border-radius:999px; padding:0.25rem 0.6rem; font-weight:700; font-size:0.85rem; }

/* -------------------------
   Cards, grids, forms
   ------------------------- */
.cards{ display:grid; gap:1rem; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
.card{ background:var(--panel-bg); border:1px solid var(--card-border); border-radius:var(--radius); padding:1rem; color:var(--fg-dark); box-shadow:var(--shadow-card); }
.card h3{ margin:0 0 0.5rem 0; }
.price{ font-size:1.1rem; color:var(--fg-dark); }

/* Forms */
.form-row{ display:flex; flex-direction:column; gap:0.25rem; margin-bottom:0.5rem; }
.form-row input, .form-row textarea, input[type="number"]{ padding:0.6rem; border-radius:8px; border:1px solid var(--card-border); font-size:1rem; }
.form-row label{ font-size:0.9rem; color:var(--muted); }

/* -------------------------
   Buttons
   ------------------------- */
.full-btn{ display:inline-flex; align-items:center; justify-content:center; gap:0.5rem; padding:0.6rem 0.9rem; border-radius:8px; background:linear-gradient(90deg,var(--primary),var(--accent)); color:#fff; border:0; text-decoration:none; cursor:pointer; font-weight:700; transition:transform var(--transition); }
.full-btn:active{ transform:translateY(1px); }
.btn-ghost{ padding:0.5rem 0.75rem; border-radius:8px; background:transparent; border:1px solid var(--card-border); color:var(--fg-dark); cursor:pointer; text-decoration:none; font-weight:700; }

/* -------------------------
   Cart modal & checkout modal
   ------------------------- */
#cart-modal{ border-radius:10px; padding:1rem; width:320px; box-shadow:0 12px 40px rgba(2,6,23,0.06); background:var(--panel-bg); border:1px solid var(--card-border); }
#modal-backdrop{ display:none; align-items:center; justify-content:center; }
#modal-backdrop.open{ display:flex; }

/* Checkout status */
#checkout-status .success{ color:#042; font-weight:800; padding:0.6rem; border-radius:8px; }

/* -------------------------
   Toast
   ------------------------- */
#qf-toast{ position:fixed; top:1rem; right:1rem; z-index:9999; display:flex; flex-direction:column; gap:0.5rem; pointer-events:none; }
#qf-toast > div{ pointer-events:auto; }

/* -------------------------
   Invoice & trace result
   ------------------------- */
#invoice-content, #trace-result{ min-height:80px; }

/* -------------------------
   Footer
   ------------------------- */
footer{ background:var(--panel-bg); border-top:1px solid var(--card-border); box-shadow:0 -6px 18px rgba(2,6,23,0.03); margin-top:2rem; padding:1rem; }
.footer-inner{ max-width:var(--container-max); margin:0 auto; display:flex; justify-content:space-between; gap:1rem; align-items:center; }

/* -------------------------
   Utilities
   ------------------------- */
.text-center{ text-align:center; }
.hidden{ display:none !important; }

/* -------------------------
   Responsive
   ------------------------- */
@media (max-width: 768px){
  .nav{ padding:0.6rem; }
  .logo{ width:40px; height:40px; }
  .nav-links{ display:none; }
  #mobile-toggle{ display:inline-flex; }
  #mobile-menu{ display:none; position:absolute; left:1rem; right:1rem; top:64px; z-index:70; padding:0.75rem; }
  .hero{ padding:1.25rem 0; }
  .container{ padding:0.75rem; }
}

/* src/js/script.js
   Robust, mobile-first cart + checkout simulation and header behavior.
   - localStorage key: 'qf_cart_v2'
   - demo order saved to 'qf_last_order'
   - Mobile toggle visibility and centered nav support
   - Added: invoice status visuals and payment confirmation with transaction id
*/
(() => {
  'use strict';

  /* ====== Config ====== */
  const CONFIG = {
    CART_KEY: 'qf_cart_v2',
    LAST_ORDER_KEY: 'qf_last_order',
    DEBUG: false,
    TOAST_DURATION: 2200
  };

  /* ====== DOM helpers ====== */
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
  const id = (n) => document.getElementById(n);

  const log = (...args) => { if (CONFIG.DEBUG) console.log('[qf]', ...args); };
  const warn = (...args) => { if (CONFIG.DEBUG) console.warn('[qf]', ...args); };

  const safeParse = (v, fallback = null) => {
    try { return JSON.parse(v); } catch { return fallback; }
  };

  const formatCurrency = (n) => {
    const num = Number(n || 0);
    if (!Number.isFinite(num)) return '$0.00';
    return '$' + num.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const escapeHtml = (s = '') =>
    String(s).replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));

  /* ====== Storage ====== */
  const loadCart = () => safeParse(localStorage.getItem(CONFIG.CART_KEY), []) || [];
  const saveCart = (cart) => {
    try { localStorage.setItem(CONFIG.CART_KEY, JSON.stringify(cart)); }
    catch (e) { warn('saveCart failed', e); }
  };

  /* ====== Toast ====== */
  function showToast(msg, ms = CONFIG.TOAST_DURATION) {
    try {
      let container = id('qf-toast');
      if (!container) {
        container = document.createElement('div');
        container.id = 'qf-toast';
        Object.assign(container.style, {
          position: 'fixed', top: '1rem', right: '1rem', zIndex: '9999',
          display: 'flex', flexDirection: 'column', gap: '0.5rem'
        });
        document.body.appendChild(container);
      }
      const el = document.createElement('div');
      el.textContent = msg;
      Object.assign(el.style, {
        background: 'rgba(2,6,23,0.04)',
        color: 'var(--fg-dark, #042028)',
        padding: '0.6rem 0.9rem',
        borderRadius: '8px',
        boxShadow: '0 8px 24px rgba(2,6,23,0.06)',
        marginTop: '0.5rem',
        transition: 'opacity 180ms ease, transform 180ms ease',
        opacity: '1'
      });
      container.appendChild(el);
      setTimeout(() => {
        el.style.opacity = '0';
        setTimeout(() => el.remove(), 220);
      }, ms);
    } catch (e) {
      log('toast error', e);
    }
  }
  // expose for inline scripts that may call it
  window.showToast = showToast;

  /* ====== Render Cart ====== */
  function renderCart() {
    const cart = loadCart();
    const cartItemsEl = id('cart-items');
    const cartTotalEl = id('cart-total');
    const headerCountEl = id('header-cart-count');

    if (!cartItemsEl || !cartTotalEl || !headerCountEl) {
      log('renderCart: missing elements'); return;
    }

    cartItemsEl.innerHTML = '';
    if (!cart.length) {
      cartItemsEl.innerHTML = '<div class="small" style="padding:0.6rem 0">Your cart is empty.</div>';
    } else {
      cart.forEach((it, idx) => {
        const row = document.createElement('div');
        row.className = 'cart-item';
        const left = document.createElement('div');
        left.innerHTML = `<div style="font-weight:700">${escapeHtml(it.title)}</div><div class="small">${it.custom ? 'Custom donation' : ''}</div>`;
        const right = document.createElement('div');
        right.style.textAlign = 'right';
        right.innerHTML = `<div style="font-weight:800">${formatCurrency(it.price)}</div>
                           <div style="margin-top:6px"><button data-idx="${idx}" class="small remove-item" style="background:transparent;border:0;color:var(--muted);cursor:pointer">Remove</button></div>`;
        row.appendChild(left);
        row.appendChild(right);
        cartItemsEl.appendChild(row);
      });
    }

    const total = cart.reduce((s, i) => s + Number(i.price || 0), 0);
    cartTotalEl.textContent = formatCurrency(total);
    headerCountEl.textContent = String(cart.length);
    log('renderCart', { count: cart.length, total });
  }

  /* ====== Add to Cart Binding ====== */
  function bindAddButtons() {
    const buttons = $$('.add-to-cart');
    if (!buttons.length) { log('no add-to-cart buttons'); }
    buttons.forEach(btn => {
      if (btn.dataset.bound === 'true') return;
      btn.dataset.bound = 'true';
      btn.addEventListener('click', (ev) => {
        ev.preventDefault();
        try {
          const title = btn.getAttribute('data-title') ||
                        (btn.closest('.card')?.querySelector('h3')?.textContent?.trim()) ||
                        'Donation';
          const priceRaw = btn.getAttribute('data-price') ||
                           btn.closest('.card')?.querySelector('.price')?.textContent ||
                           '0';
          const price = Number(String(priceRaw).replace(/[^0-9.]/g, '')) || 0;
          const cart = loadCart();
          cart.push({ title: title.trim(), price: Number(price), addedAt: new Date().toISOString() });
          saveCart(cart);
          renderCart();
          showToast(`Added to cart: ${title}`);
        } catch (err) {
          warn('add-to-cart handler error', err);
          showToast('Could not add item to cart');
        }
      });
    });
  }

  /* ====== Custom Donation ====== */
  function bindCustomDonation() {
    const input = id('custom-amount');
    const addBtn = id('custom-add');
    if (!input || !addBtn) return;

    const validate = () => {
      const v = Number(input.value);
      const ok = Number.isFinite(v) && v >= 1;
      addBtn.disabled = !ok;
      if (!ok) addBtn.setAttribute('aria-disabled', 'true'); else addBtn.removeAttribute('aria-disabled');
    };

    input.addEventListener('input', validate);
    addBtn.addEventListener('click', (e) => {
      e.preventDefault();
      const v = Number(input.value);
      if (!Number.isFinite(v) || v < 1) { showToast('Enter a valid amount (minimum $1)'); return; }
      const cart = loadCart();
      cart.push({ title: 'Custom Donation', price: Number(v), custom: true, addedAt: new Date().toISOString() });
      saveCart(cart);
      renderCart();
      showToast('Custom donation added');
      input.value = '';
      addBtn.disabled = true;
      addBtn.setAttribute('aria-disabled', 'true');
    });
  }

  /* ====== Cart Interactions ====== */
  function bindCartInteractions() {
    const headerCart = id('header-cart');
    const cartModal = id('cart-modal');
    const cartClear = id('cart-clear');
    const cartItems = id('cart-items');

    if (headerCart && cartModal) {
      headerCart.addEventListener('click', () => {
        const open = cartModal.classList.toggle('open');
        cartModal.style.display = open ? 'block' : 'none';
        cartModal.setAttribute('aria-hidden', open ? 'false' : 'true');
      });
    }

    if (cartClear) {
      cartClear.addEventListener('click', () => {
        if (!confirm('Clear all items from cart?')) return;
        saveCart([]);
        renderCart();
        showToast('Cart cleared');
      });
    }

    if (cartItems) {
      cartItems.addEventListener('click', (e) => {
        const btn = e.target.closest('button.remove-item');
        if (!btn) return;
        const idx = Number(btn.getAttribute('data-idx'));
        const cart = loadCart();
        if (Number.isInteger(idx) && idx >= 0 && idx < cart.length) {
          cart.splice(idx, 1);
          saveCart(cart);
          renderCart();
          showToast('Item removed');
        } else {
          warn('remove-item: invalid index', idx);
        }
      });
    }
  }

  /* ====== Checkout Simulation ====== */
  function bindCheckout() {
    const checkoutBtn = id('checkout');
    const modalBackdrop = id('modal-backdrop');
    const checkoutForm = id('checkout-form');
    const checkoutStatus = id('checkout-status');
    const cancelBtn = id('cancel-checkout');

    if (checkoutBtn && modalBackdrop) {
      checkoutBtn.addEventListener('click', () => {
        const cart = loadCart();
        if (!cart.length) { showToast('Your cart is empty'); return; }
        modalBackdrop.classList.add('open');
        modalBackdrop.style.display = 'flex';
        modalBackdrop.setAttribute('aria-hidden', 'false');
      });
    }

    if (cancelBtn && modalBackdrop) {
      cancelBtn.addEventListener('click', () => {
        modalBackdrop.classList.remove('open');
        modalBackdrop.style.display = 'none';
        modalBackdrop.setAttribute('aria-hidden', 'true');
      });
    }

    if (modalBackdrop) {
      modalBackdrop.addEventListener('click', (e) => {
        if (e.target === modalBackdrop) {
          modalBackdrop.classList.remove('open');
          modalBackdrop.style.display = 'none';
          modalBackdrop.setAttribute('aria-hidden', 'true');
        }
      });
    }

    const payMethods = $$('.pay-method');
    if (payMethods.length) {
      payMethods.forEach(pm => {
        pm.addEventListener('click', () => {
          payMethods.forEach(x => x.classList.remove('active'));
          pm.classList.add('active');
          const method = pm.dataset.method;
          const paymentDetails = id('payment-details');
          if (!paymentDetails) return;
          if (method === 'card') {
            paymentDetails.innerHTML = '<div class="form-row single"><label class="small" for="card-number">Card number</label><input id="card-number" name="card" type="text" inputmode="numeric" placeholder="4242 4242 4242 4242" /></div>';
          } else if (method === 'bank') {
            paymentDetails.innerHTML = `<div class="form-row single"><label class="small">Bank transfer instructions</label><div class="small">Use reference: <strong>${Math.random().toString(36).slice(2,9).toUpperCase()}</strong></div></div>`;
          } else {
            paymentDetails.innerHTML = '<div class="form-row single"><label class="small">Mobile wallet</label><div class="small">Enter mobile number at payment step</div></div>';
          }
        });
      });
    }

    if (checkoutForm) {
      checkoutForm.addEventListener('submit', (e) => {
        e.preventDefault();
        try {
          const name = id('payer-name')?.value.trim() || '';
          const email = id('payer-email')?.value.trim() || '';
          if (!name || !email) { showToast('Please provide name and email'); return; }

          checkoutForm.style.display = 'none';
          if (checkoutStatus) { checkoutStatus.style.display = ''; checkoutStatus.innerHTML = '<div class="small">Processing payment…</div>'; }

          setTimeout(() => {
            const cart = loadCart();
            const total = cart.reduce((s, i) => s + Number(i.price || 0), 0);
            const order = {
              id: 'QF-' + Math.random().toString(36).slice(2, 9).toUpperCase(),
              items: cart,
              donor: { name, email },
              total: Number(total),
              status: 'paid',
              createdAt: new Date().toISOString()
            };
            try { localStorage.setItem(CONFIG.LAST_ORDER_KEY, JSON.stringify(order)); } catch (err) { warn('save order failed', err); }

            saveCart([]);
            renderCart();

            if (checkoutStatus) checkoutStatus.innerHTML = '<div class="success" style="background:linear-gradient(90deg,#10b981,#06b6d4);color:#042;padding:0.6rem;border-radius:8px;font-weight:800">Payment successful — thank you.</div>';
            showToast('Payment completed. Receipt saved locally.');

            setTimeout(() => {
              if (modalBackdrop) { modalBackdrop.classList.remove('open'); modalBackdrop.style.display = 'none'; modalBackdrop.setAttribute('aria-hidden', 'true'); }
              if (checkoutStatus) checkoutStatus.style.display = 'none';
              if (checkoutForm) checkoutForm.style.display = '';
              if (location.pathname.endsWith('/donate.html') || location.pathname.endsWith('/')) {
                location.href = './thankyou.html';
              }
            }, 1200);
          }, 1200);
        } catch (err) {
          warn('checkout submit error', err);
          showToast('Payment failed (demo). Try again.');
          if (checkoutForm) checkoutForm.style.display = '';
          if (checkoutStatus) checkoutStatus.style.display = 'none';
        }
      });
    }
  }

  /* ====== Mobile Menu ====== */
  function bindMobileMenu() {
    const toggle = id('mobile-toggle');
    const mobileMenu = id('mobile-menu');
    const primaryNav = id('primary-nav');
    if (!toggle) return;

    const updateToggleVisibility = () => {
      toggle.style.display = window.innerWidth <= 768 ? 'inline-flex' : 'none';
    };
    updateToggleVisibility();
    window.addEventListener('resize', updateToggleVisibility);

    toggle.addEventListener('click', (e) => {
      e.preventDefault();
      const expanded = toggle.getAttribute('aria-expanded') === 'true';
      toggle.setAttribute('aria-expanded', String(!expanded));
      if (mobileMenu) {
        mobileMenu.style.display = expanded ? 'none' : 'block';
      } else if (primaryNav) {
        primaryNav.style.display = expanded ? 'none' : 'flex';
        primaryNav.style.flexDirection = 'column';
        primaryNav.style.gap = '0.5rem';
      }
    });

    document.addEventListener('click', (ev) => {
      if (!mobileMenu) return;
      if (!mobileMenu.contains(ev.target) && !toggle.contains(ev.target)) {
        mobileMenu.style.display = 'none';
        toggle.setAttribute('aria-expanded', 'false');
      }
    });
  }

  /* ====== Invoice Page (enhanced) ====== */
  function renderInvoicePage() {
    const el = id('invoice-content');
    if (!el) return;
    const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
    if (!order) {
      el.innerHTML = '<p class="small">No invoice found. Complete a donation to generate an invoice.</p>';
      return;
    }

    // status badge
    const status = (order.status || 'unpaid').toLowerCase();
    const badgeColor = status === 'paid' ? '#059669' : (status === 'pending' ? '#b45309' : '#b45309');
    const statusLabel = status === 'paid' ? 'Paid' : (status === 'pending' ? 'Pending' : 'Unpaid');

    const itemsHtml = (order.items || []).map(it => `<div style="display:flex;justify-content:space-between;padding:6px 0"><div>${escapeHtml(it.title)}</div><div>${formatCurrency(it.price)}</div></div>`).join('');

    const txHtml = order.txId ? `<div class="small">Transaction ID: <strong>${escapeHtml(order.txId)}</strong></div>` : '';
    const paidAtHtml = order.paidAt ? `<div class="small">Paid at: ${new Date(order.paidAt).toLocaleString()}</div>` : '';

    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;gap:1rem">
        <div>
          <div><strong>Order ID:</strong> ${escapeHtml(order.id)}</div>
          <div class="small">Donor: ${escapeHtml(order.donor?.name || '')} • ${escapeHtml(order.donor?.email || '')}</div>
          ${txHtml}
          ${paidAtHtml}
        </div>
        <div style="text-align:right">
          <div style="font-weight:800">${formatCurrency(order.total)}</div>
          <div style="margin-top:6px"><span style="display:inline-block;padding:0.35rem 0.6rem;border-radius:999px;background:${badgeColor};color:#fff;font-weight:800">${statusLabel}</span></div>
        </div>
      </div>
      <div style="margin-top:12px">${itemsHtml}</div>
    `;
  }

  /* ====== Payment confirmation binding (centralized) ====== */
  function bindPaymentConfirmation() {
    const confirmBtn = id('confirm-payment');
    if (!confirmBtn) return;

    confirmBtn.addEventListener('click', () => {
      const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
      if (!order) { showToast('No order found to confirm'); return; }

      // Ask for transaction id (simple prompt for demo)
      const tx = prompt('Enter transaction/reference ID (copy from your payment receipt). Leave blank to confirm without ID.');
      if (tx === null) {
        // user cancelled
        return;
      }

      order.status = 'paid';
      order.txId = tx ? String(tx).trim() : '';
      order.paidAt = new Date().toISOString();

      try {
        localStorage.setItem(CONFIG.LAST_ORDER_KEY, JSON.stringify(order));
      } catch (e) {
        warn('save order failed', e);
        showToast('Could not save confirmation locally');
        return;
      }

      showToast('Payment confirmed — thank you.');
      // small delay so user sees toast, then go to invoice
      setTimeout(() => {
        location.href = './invoice.html';
      }, 700);
    });
  }

  /* ====== Tracing ====== */
  function bindTracing() {
    const btn = id('trace-btn');
    if (!btn) return;
    btn.addEventListener('click', () => {
      const q = (id('trace-input')?.value || '').trim();
      const out = id('trace-result');
      if (!out) return;
      if (!q) { out.innerHTML = '<div class="small">Enter order id, email or phone</div>'; return; }
      const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
      if (!order) { out.innerHTML = '<div class="small">No orders found (demo). In production, query your backend.</div>'; return; }

      const qLower = q.toLowerCase();
      const matches = (q === order.id) || (qLower === (order.donor?.email || '').toLowerCase()) || (q === (order.donor?.phone || ''));

      if (matches) {
        out.innerHTML = `<div><strong>Status:</strong> ${escapeHtml(order.status)}</div>
                         <div class="small">Order ID: ${escapeHtml(order.id)}</div>
                         <div class="small">Donor: ${escapeHtml(order.donor?.name || '')} • ${escapeHtml(order.donor?.phone || '')}</div>
                         <div style="margin-top:8px"><a class="full-btn" href="./invoice.html">View Invoice</a></div>`;
      } else {
        out.innerHTML = '<div class="small">No matching order found in demo data.</div>';
      }
    });
  }

  /* ====== Diagnostics ====== */
  function diagnosticLog() {
    if (!CONFIG.DEBUG) return;
    log('Diagnostic: DOM elements presence', {
      addToCartButtons: $$('.add-to-cart').length,
      headerCart: !!id('header-cart'),
      headerCartCount: !!id('header-cart-count'),
      cartModal: !!id('cart-modal'),
      cartItems: !!id('cart-items'),
      cartTotal: !!id('cart-total'),
      checkout: !!id('checkout'),
      customAmount: !!id('custom-amount'),
      customAdd: !!id('custom-add'),
      mobileToggle: !!id('mobile-toggle'),
      confirmPayment: !!id('confirm-payment')
    });
  }

  /* ====== Init ====== */
  function init() {
    try {
      bindAddButtons();
      bindCustomDonation();
      bindCartInteractions();
      bindCheckout();
      bindMobileMenu();
      renderCart();
      renderInvoicePage();
      bindTracing();
      bindPaymentConfirmation();
      diagnosticLog();
      log('init complete');
    } catch (e) {
      warn('init error', e);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* css/style.css
   Polished, international donation UI
   Variables, responsive layout, accessible components
*/

:root{
  --page-bg:#faf9f7;
  --panel-bg:#ffffff;
  --muted:#6b7280;
  --primary:#0ea5a4;
  --accent:#06b6d4;
  --fg:#042028;
  --card-border:rgba(2,6,23,0.06);
  --radius:12px;
  --container:1100px;
  --shadow-soft:0 6px 18px rgba(2,6,23,0.04);
  --shadow-card:0 8px 30px rgba(2,6,23,0.04);
  --gap:1rem;
  --text-sm:0.9rem;
  --success:#059669;
  --warning:#b45309;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;color:var(--fg);background:var(--page-bg);-webkit-font-smoothing:antialiased}
.container{max-width:var(--container);margin:0 auto;padding:1.25rem}

/* Header */
header{background:var(--panel-bg);border-bottom:1px solid var(--card-border);box-shadow:var(--shadow-soft);position:sticky;top:0;z-index:60}
.nav{display:flex;align-items:center;justify-content:space-between;gap:var(--gap);padding:0.8rem 1rem;max-width:var(--container);margin:0 auto}
.brand{display:flex;align-items:center;gap:0.75rem;text-decoration:none;color:var(--fg)}
.logo{width:48px;height:48px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;font-weight:800;background:linear-gradient(135deg,var(--primary),var(--accent));color:#fff;box-shadow:var(--shadow-soft);object-fit:cover}
.brand-title{font-weight:800;font-size:1rem}
.brand-sub{font-size:0.9rem;color:var(--muted)}

/* Nav links */
.nav-links{display:flex;gap:0.6rem;align-items:center}
.nav-link{padding:0.45rem 0.8rem;border-radius:8px;color:var(--fg);font-weight:700;text-decoration:none}
.nav-link:hover{background:rgba(2,6,23,0.02)}

/* Cart */
.header-cart{display:flex;align-items:center;gap:0.5rem;padding:0.35rem 0.6rem;border-radius:8px;cursor:pointer}
.cart-count{background:var(--primary);color:#fff;padding:0.12rem 0.45rem;border-radius:999px;font-weight:800;font-size:0.85rem}

/* Hero */
.hero{padding:2rem 0;display:flex;align-items:center;gap:1.25rem}
.kicker{display:inline-block;color:var(--primary);background:rgba(14,165,164,0.06);border-radius:999px;padding:0.25rem 0.6rem;font-weight:700;font-size:0.9rem}
.lead{color:var(--muted);margin-top:0.5rem}

/* Cards and forms */
.card{background:var(--panel-bg);border:1px solid var(--card-border);border-radius:var(--radius);padding:1rem;color:var(--fg);box-shadow:var(--shadow-card)}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.price{font-weight:800;font-size:1.05rem}
.form-row{display:flex;flex-direction:column;gap:0.25rem;margin-bottom:0.5rem}
.form-row input,.form-row select,textarea{padding:0.6rem;border-radius:8px;border:1px solid var(--card-border);font-size:1rem}
.form-row label{font-size:0.95rem;color:var(--muted)}

/* Buttons */
.full-btn{display:inline-flex;align-items:center;justify-content:center;padding:0.6rem 0.9rem;border-radius:8px;background:linear-gradient(90deg,var(--primary),var(--accent));color:#fff;border:0;cursor:pointer;font-weight:700;text-decoration:none}
.btn-ghost{padding:0.5rem 0.75rem;border-radius:8px;background:transparent;border:1px solid var(--card-border);color:var(--fg);cursor:pointer}

/* Modal / cart */
#cart-modal{position:fixed;right:1rem;top:4rem;width:360px;padding:1rem;z-index:80;border-radius:12px}
#modal-backdrop{display:none;align-items:center;justify-content:center}
#modal-backdrop.open{display:flex}
#qf-toast{position:fixed;top:1rem;right:1rem;z-index:9999;display:flex;flex-direction:column;gap:0.5rem;pointer-events:none}
#qf-toast>div{pointer-events:auto}

/* Invoice visuals */
.badge{display:inline-block;padding:0.35rem 0.6rem;border-radius:999px;color:#fff;font-weight:800}
.badge-paid{background:var(--success)}
.badge-unpaid{background:var(--warning)}

/* Utilities */
.small{font-size:var(--text-sm);color:var(--muted)}
.text-center{text-align:center}
.hidden{display:none!important}

/* Responsive */
@media (max-width:768px){
  .nav{padding:0.6rem}
  .logo{width:40px;height:40px}
  .nav-links{display:none}
  #mobile-toggle{display:inline-flex}
  .container{padding:0.75rem}
  #cart-modal{right:0;left:0;margin:0 auto;width:calc(100% - 2rem)}
}

/* js/script.js
   Polished donation flow with manual payment UX
   - localStorage keys: qf_cart_v2, qf_last_order
   - Exposes showToast globally for inline scripts
*/

(() => {
  'use strict';

  const CONFIG = {
    CART_KEY: 'qf_cart_v2',
    LAST_ORDER_KEY: 'qf_last_order',
    TOAST_MS: 2200,
    DEBUG: false
  };

  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const id = (n) => document.getElementById(n);

  const log = (...a) => { if (CONFIG.DEBUG) console.log('[qf]', ...a); };
  const warn = (...a) => { if (CONFIG.DEBUG) console.warn('[qf]', ...a); };

  const safeParse = (v, fallback = null) => { try { return JSON.parse(v); } catch { return fallback; } };
  const formatCurrency = (n) => { const num = Number(n || 0); if (!Number.isFinite(num)) return '$0.00'; return '$' + num.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); };
  const escapeHtml = (s = '') => String(s).replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));

  // Storage helpers
  const loadCart = () => safeParse(localStorage.getItem(CONFIG.CART_KEY), []) || [];
  const saveCart = (cart) => { try { localStorage.setItem(CONFIG.CART_KEY, JSON.stringify(cart)); } catch (e) { warn('saveCart', e); } };

  // Toast
  function showToast(msg, ms = CONFIG.TOAST_MS) {
    try {
      let container = id('qf-toast');
      if (!container) {
        container = document.createElement('div');
        container.id = 'qf-toast';
        Object.assign(container.style, { position: 'fixed', top: '1rem', right: '1rem', zIndex: '9999', display: 'flex', flexDirection: 'column', gap: '0.5rem' });
        document.body.appendChild(container);
      }
      const el = document.createElement('div');
      el.textContent = msg;
      Object.assign(el.style, { background: 'rgba(2,6,23,0.04)', color: 'var(--fg)', padding: '0.6rem 0.9rem', borderRadius: '8px', boxShadow: '0 8px 24px rgba(2,6,23,0.06)', transition: 'opacity 180ms ease' });
      container.appendChild(el);
      setTimeout(() => { el.style.opacity = '0'; setTimeout(() => el.remove(), 220); }, ms);
    } catch (e) { log('toast error', e); }
  }
  window.showToast = showToast;

  // Render cart UI
  function renderCart() {
    const cart = loadCart();
    const itemsEl = id('cart-items');
    const totalEl = id('cart-total');
    const countEl = id('header-cart-count');
    if (!itemsEl || !totalEl || !countEl) return;

    itemsEl.innerHTML = '';
    if (!cart.length) {
      itemsEl.innerHTML = '<div class="small" style="padding:0.6rem 0">Your cart is empty.</div>';
    } else {
      cart.forEach((it, idx) => {
        const row = document.createElement('div');
        row.style.display = 'flex';
        row.style.justifyContent = 'space-between';
        row.style.padding = '8px 0';
        row.innerHTML = `<div><div style="font-weight:700">${escapeHtml(it.title)}</div><div class="small">${it.custom ? 'Custom donation' : ''}</div></div>
                         <div style="text-align:right"><div style="font-weight:800">${formatCurrency(it.price)}</div><div style="margin-top:6px"><button data-idx="${idx}" class="small remove-item" style="background:transparent;border:0;color:var(--muted);cursor:pointer">Remove</button></div></div>`;
        itemsEl.appendChild(row);
      });
    }

    const total = cart.reduce((s, i) => s + Number(i.price || 0), 0);
    totalEl.textContent = formatCurrency(total);
    countEl.textContent = String(cart.length);
  }

  // Add buttons
  function bindAddButtons() {
    const buttons = $$('.add-to-cart');
    buttons.forEach(btn => {
      if (btn.dataset.bound === 'true') return;
      btn.dataset.bound = 'true';
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        try {
          const title = btn.getAttribute('data-title') || (btn.closest('.card')?.querySelector('h3')?.textContent?.trim()) || 'Donation';
          const priceRaw = btn.getAttribute('data-price') || btn.closest('.card')?.querySelector('.price')?.textContent || '0';
          const price = Number(String(priceRaw).replace(/[^0-9.]/g, '')) || 0;
          const cart = loadCart();
          cart.push({ title: title.trim(), price: Number(price), addedAt: new Date().toISOString() });
          saveCart(cart);
          renderCart();
          showToast(`Added to cart: ${title}`);
        } catch (err) { warn('add error', err); showToast('Could not add item'); }
      });
    });
  }

  // Custom donation
  function bindCustomDonation() {
    const input = id('custom-amount');
    const addBtn = id('custom-add');
    if (!input || !addBtn) return;
    input.addEventListener('input', () => {
      const v = Number(input.value);
      const ok = Number.isFinite(v) && v >= 1;
      addBtn.disabled = !ok;
      if (!ok) addBtn.setAttribute('aria-disabled', 'true'); else addBtn.removeAttribute('aria-disabled');
    });
    addBtn.addEventListener('click', (e) => {
      e.preventDefault();
      const v = Number(input.value);
      if (!Number.isFinite(v) || v < 1) { showToast('Enter a valid amount (minimum $1)'); return; }
      const cart = loadCart();
      cart.push({ title: 'Custom Donation', price: Number(v), custom: true, addedAt: new Date().toISOString() });
      saveCart(cart);
      renderCart();
      showToast('Custom donation added');
      input.value = '';
      addBtn.disabled = true;
      addBtn.setAttribute('aria-disabled', 'true');
    });
  }

  // Cart interactions
  function bindCartInteractions() {
    const headerCart = id('header-cart');
    const cartModal = id('cart-modal');
    const cartClear = id('cart-clear');
    const cartItems = id('cart-items');

    if (headerCart && cartModal) {
      headerCart.addEventListener('click', () => {
        const open = cartModal.classList.toggle('open');
        cartModal.style.display = open ? 'block' : 'none';
        cartModal.setAttribute('aria-hidden', open ? 'false' : 'true');
      });
    }

    if (cartClear) {
      cartClear.addEventListener('click', () => {
        if (!confirm('Clear all items from cart?')) return;
        saveCart([]);
        renderCart();
        showToast('Cart cleared');
      });
    }

    if (cartItems) {
      cartItems.addEventListener('click', (e) => {
        const btn = e.target.closest('button.remove-item');
        if (!btn) return;
        const idx = Number(btn.getAttribute('data-idx'));
        const cart = loadCart();
        if (Number.isInteger(idx) && idx >= 0 && idx < cart.length) {
          cart.splice(idx, 1);
          saveCart(cart);
          renderCart();
          showToast('Item removed');
        } else warn('invalid index', idx);
      });
    }
  }

  // Checkout modal and form (if present)
  function bindCheckout() {
    const checkoutBtn = id('checkout');
    const modalBackdrop = id('modal-backdrop');
    const checkoutForm = id('checkout-form');
    const checkoutStatus = id('checkout-status');
    const cancelBtn = id('cancel-checkout');

    if (checkoutBtn && modalBackdrop) {
      checkoutBtn.addEventListener('click', () => {
        const cart = loadCart();
        if (!cart.length) { showToast('Your cart is empty'); return; }
        modalBackdrop.classList.add('open');
        modalBackdrop.style.display = 'flex';
        modalBackdrop.setAttribute('aria-hidden', 'false');
      });
    }

    if (cancelBtn && modalBackdrop) {
      cancelBtn.addEventListener('click', () => {
        modalBackdrop.classList.remove('open');
        modalBackdrop.style.display = 'none';
        modalBackdrop.setAttribute('aria-hidden', 'true');
      });
    }

    if (modalBackdrop) {
      modalBackdrop.addEventListener('click', (e) => {
        if (e.target === modalBackdrop) {
          modalBackdrop.classList.remove('open');
          modalBackdrop.style.display = 'none';
          modalBackdrop.setAttribute('aria-hidden', 'true');
        }
      });
    }

    if (checkoutForm) {
      checkoutForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const name = id('payer-name')?.value.trim() || '';
        const email = id('payer-email')?.value.trim() || '';
        if (!name || !email) { showToast('Please provide name and email'); return; }
        // Demo: immediate paid flow (kept for backward compatibility)
        checkoutForm.style.display = 'none';
        if (checkoutStatus) { checkoutStatus.style.display = ''; checkoutStatus.innerHTML = '<div class="small">Processing…</div>'; }
        setTimeout(() => {
          const cart = loadCart();
          const total = cart.reduce((s, i) => s + Number(i.price || 0), 0);
          const order = {
            id: 'QF-' + Math.random().toString(36).slice(2, 9).toUpperCase(),
            items: cart,
            donor: { name, email },
            total: Number(total),
            status: 'paid',
            createdAt: new Date().toISOString(),
            paidAt: new Date().toISOString()
          };
          try { localStorage.setItem(CONFIG.LAST_ORDER_KEY, JSON.stringify(order)); } catch (e) { warn(e); }
          saveCart([]);
          renderCart();
          if (checkoutStatus) checkoutStatus.innerHTML = '<div class="small" style="background:linear-gradient(90deg,#10b981,#06b6d4);color:#042;padding:0.6rem;border-radius:8px;font-weight:800">Payment successful — thank you.</div>';
          showToast('Payment completed. Receipt saved locally.');
          setTimeout(() => { if (modalBackdrop) { modalBackdrop.classList.remove('open'); modalBackdrop.style.display = 'none'; modalBackdrop.setAttribute('aria-hidden', 'true'); } location.href = './thankyou.html'; }, 900);
        }, 900);
      });
    }
  }

  // Mobile menu
  function bindMobileMenu() {
    const toggle = id('mobile-toggle');
    const mobileMenu = id('mobile-menu');
    const primaryNav = id('primary-nav');
    if (!toggle) return;
    const update = () => { toggle.style.display = window.innerWidth <= 768 ? 'inline-flex' : 'none'; };
    update();
    window.addEventListener('resize', update);
    toggle.addEventListener('click', (e) => {
      e.preventDefault();
      const expanded = toggle.getAttribute('aria-expanded') === 'true';
      toggle.setAttribute('aria-expanded', String(!expanded));
      if (mobileMenu) mobileMenu.style.display = expanded ? 'none' : 'block';
      else if (primaryNav) { primaryNav.style.display = expanded ? 'none' : 'flex'; primaryNav.style.flexDirection = 'column'; primaryNav.style.gap = '0.5rem'; }
    });
    document.addEventListener('click', (ev) => {
      if (!mobileMenu) return;
      if (!mobileMenu.contains(ev.target) && !toggle.contains(ev.target)) { mobileMenu.style.display = 'none'; toggle.setAttribute('aria-expanded', 'false'); }
    });
  }

  // Invoice rendering (status-aware)
  function renderInvoicePage() {
    const el = id('invoice-content');
    if (!el) return;
    const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
    if (!order) { el.innerHTML = '<p class="small">No invoice found. Complete a donation to generate an invoice.</p>'; return; }
    const status = (order.status || 'unpaid').toLowerCase();
    const badgeClass = status === 'paid' ? 'badge badge-paid' : 'badge badge-unpaid';
    const itemsHtml = (order.items || []).map(it => `<div style="display:flex;justify-content:space-between;padding:6px 0"><div>${escapeHtml(it.title)}</div><div>${formatCurrency(it.price)}</div></div>`).join('');
    const txHtml = order.txId ? `<div class="small">Transaction ID: <strong>${escapeHtml(order.txId)}</strong></div>` : '';
    const paidAtHtml = order.paidAt ? `<div class="small">Paid at: ${new Date(order.paidAt).toLocaleString()}</div>` : '';
    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;gap:1rem">
        <div>
          <div><strong>Order ID:</strong> ${escapeHtml(order.id)}</div>
          <div class="small">Donor: ${escapeHtml(order.donor?.name || '')} • ${escapeHtml(order.donor?.email || '')}</div>
          ${txHtml}
          ${paidAtHtml}
        </div>
        <div style="text-align:right">
          <div style="font-weight:800">${formatCurrency(order.total)}</div>
          <div style="margin-top:6px"><span class="${badgeClass}">${status === 'paid' ? 'Paid' : 'Unpaid'}</span></div>
        </div>
      </div>
      <div style="margin-top:12px">${itemsHtml}</div>
    `;
  }

  // Payment confirmation binding for payment.html
  function bindPaymentPage() {
    const confirmBtn = id('confirm-payment');
    if (!confirmBtn) return;
    confirmBtn.addEventListener('click', () => {
      const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
      if (!order) { showToast('No order found to confirm'); return; }
      // Ask for transaction id
      const tx = prompt('Enter transaction/reference ID (optional). Paste the ID from your payment receipt.');
      if (tx === null) return; // cancelled
      order.status = 'paid';
      order.txId = tx ? String(tx).trim() : '';
      order.paidAt = new Date().toISOString();
      try { localStorage.setItem(CONFIG.LAST_ORDER_KEY, JSON.stringify(order)); } catch (e) { warn(e); showToast('Could not save confirmation'); return; }
      showToast('Payment confirmed — thank you.');
      setTimeout(() => { location.href = './invoice.html'; }, 700);
    });
  }

  // Copy helpers for payment details
  function bindCopyButtons() {
    const copyButtons = $$('.copy-btn');
    copyButtons.forEach(btn => {
      if (btn.dataset.bound === 'true') return;
      btn.dataset.bound = 'true';
      btn.addEventListener('click', async () => {
        const target = btn.getAttribute('data-copy') || '';
        try {
          await navigator.clipboard.writeText(target);
          showToast('Copied to clipboard');
        } catch {
          showToast('Copy failed — please select and copy manually');
        }
      });
    });
  }

  // Tracing
  function bindTracing() {
    const btn = id('trace-btn');
    if (!btn) return;
    btn.addEventListener('click', () => {
      const q = (id('trace-input')?.value || '').trim();
      const out = id('trace-result');
      if (!out) return;
      if (!q) { out.innerHTML = '<div class="small">Enter order id, email or phone</div>'; return; }
      const order = safeParse(localStorage.getItem(CONFIG.LAST_ORDER_KEY), null);
      if (!order) { out.innerHTML = '<div class="small">No orders found (demo).</div>'; return; }
      const qLower = q.toLowerCase();
      const matches = (q === order.id) || (qLower === (order.donor?.email || '').toLowerCase()) || (q === (order.donor?.phone || ''));
      if (matches) {
        out.innerHTML = `<div><strong>Status:</strong> ${escapeHtml(order.status)}</div>
                         <div class="small">Order ID: ${escapeHtml(order.id)}</div>
                         <div class="small">Donor: ${escapeHtml(order.donor?.name || '')} • ${escapeHtml(order.donor?.phone || '')}</div>
                         <div style="margin-top:8px"><a class="full-btn" href="./invoice.html">View Invoice</a></div>`;
      } else out.innerHTML = '<div class="small">No matching order found in demo data.</div>';
    });
  }

  // Diagnostics
  function diagnosticLog() {
    if (!CONFIG.DEBUG) return;
    log('diagnostic', {
      addToCart: $$('.add-to-cart').length,
      headerCart: !!id('header-cart'),
      cartModal: !!id('cart-modal'),
      invoice: !!id('invoice-content'),
      confirmPayment: !!id('confirm-payment')
    });
  }

  // Init
  function init() {
    try {
      bindAddButtons();
      bindCustomDonation();
      bindCartInteractions();
      bindCheckout();
      bindMobileMenu();
      renderCart();
      renderInvoicePage();
      bindPaymentPage();
      bindCopyButtons();
      bindTracing();
      diagnosticLog();
      log('init complete');
    } catch (e) { warn('init error', e); }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();

})();

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
add_codecraft.py — CodeCraft এ নতুন এন্ট্রি যোগ করার স্ক্রিপ্ট

ব্যবহার:
    python add_codecraft.py           নতুন এন্ট্রি যোগ করুন
    python add_codecraft.py serve     ব্রাউজারে দেখার জন্য লোকাল সার্ভার চালু করুন (পোর্ট 8000)
    python add_codecraft.py serve 9000
    python add_codecraft.py list      সব এন্ট্রির তালিকা দেখুন
    python add_codecraft.py delete    একটি এন্ট্রি মুছুন
"""

import json
import os
import re
import sys
import time
import urllib.parse
import urllib.request

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_FILE = os.path.join(BASE_DIR, "data.json")

DEFAULT_MENUS = ["স্ক্রিপ্ট", "ফাইল", "নির্দেশনা"]

# ফাইলের এক্সটেনশন থেকে ভাষা/লেবেল চেনার তালিকা
EXT_LANG = {
    ".html": "HTML", ".htm": "HTML", ".css": "CSS",
    ".json": "JSON", ".py": "Python",
    ".js": "Node", ".mjs": "Node", ".cjs": "Node",
    ".ts": "TypeScript", ".sh": "Bash", ".bash": "Bash", ".zsh": "Bash",
    ".php": "PHP", ".java": "Java", ".c": "C", ".cpp": "C++", ".cs": "C#",
    ".go": "Go", ".rs": "Rust", ".sql": "SQL",
    ".yml": "YAML", ".yaml": "YAML", ".xml": "XML",
    ".md": "Markdown", ".txt": "Text", ".env": "Text", ".ini": "Text",
}


# ---------------------------------------------------------------- data file --
def load_data():
    if not os.path.exists(DATA_FILE):
        return {
            "site": {
                "title": "CodeCraft",
                "subtitle": "আমার স্ক্রিপ্ট, ফাইল ও নির্দেশনার সংগ্রহ",
            },
            "menus": list(DEFAULT_MENUS),
            "items": [],
        }
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        data = json.load(f)
    data.setdefault("site", {"title": "CodeCraft", "subtitle": ""})
    data.setdefault("menus", list(DEFAULT_MENUS))
    data.setdefault("items", [])
    return data


def save_data(data):
    tmp = DATA_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    os.replace(tmp, DATA_FILE)  # আধা-লেখা ফাইল থেকে ডাটা নষ্ট হওয়া ঠেকায়


def all_menus(data):
    menus = list(data["menus"])
    for it in data["items"]:
        if it.get("menu") and it["menu"] not in menus:
            menus.append(it["menu"])
    return menus


# ------------------------------------------------------------------- input --
def ask(prompt, required=True, default=None):
    while True:
        suffix = f" [{default}]" if default else ""
        try:
            value = input(f"{prompt}{suffix}: ").strip()
        except EOFError:
            print("\nইনপুট শেষ হয়ে গেছে, বন্ধ করা হলো।")
            sys.exit(1)
        if not value and default:
            return default
        if value or not required:
            return value
        print("  ⚠ এটি খালি রাখা যাবে না।")


def ask_multiline(prompt):
    print(f"{prompt} (একাধিক লাইন লিখতে পারেন; শেষ করতে একটি খালি লাইনে Enter চাপুন)")
    lines = []
    while True:
        try:
            line = input("  > ")
        except EOFError:
            break
        if line == "":
            if lines:
                break
            print("  ⚠ বিবরণ খালি রাখা যাবে না।")
            continue
        lines.append(line)
    return "\n".join(lines)


def choose_menu(data):
    menus = all_menus(data)
    print("\nকোন মেনুর আওতায় যোগ করবেন?")
    for i, name in enumerate(menus, 1):
        print(f"  {i}. {name}")
    custom_no = len(menus) + 1
    print(f"  {custom_no}. ➕ কাস্টম মেনু (নিজে লিখবো)")
    while True:
        raw = ask("নম্বর লিখুন (অথবা সরাসরি মেনুর নাম লিখুন)")
        if raw.isdigit():
            n = int(raw)
            if 1 <= n <= len(menus):
                return menus[n - 1]
            if n == custom_no:
                return ask("নতুন মেনুর নাম")
            print("  ⚠ ভুল নম্বর।")
        else:
            return raw  # সরাসরি নাম লিখলে সেটাই মেনু


# ------------------------------------------------------------ file / source --
def to_raw_github(url):
    """github.com/…/blob/… লিংককে raw লিংকে বদলায়।"""
    m = re.match(r"^https?://github\.com/([^/]+)/([^/]+)/blob/(.+)$", url)
    if m:
        return f"https://raw.githubusercontent.com/{m.group(1)}/{m.group(2)}/{m.group(3)}"
    return url


def read_source(src):
    """(কোড, ফাইলের নাম) ফেরত দেয়। ব্যর্থ হলে None।"""
    if re.match(r"^https?://", src, re.I):
        url = to_raw_github(src)
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "CodeCraft/1.0"})
            with urllib.request.urlopen(req, timeout=20) as resp:
                raw = resp.read()
        except Exception as e:
            print(f"  ⚠ লিংক থেকে আনা যায়নি: {e}")
            return None
        name = os.path.basename(urllib.parse.urlparse(url).path) or "file.txt"
    else:
        path = os.path.expanduser(src.strip('"').strip("'"))
        candidates = [path] if os.path.isabs(path) else [
            os.path.join(BASE_DIR, path),      # এই স্ক্রিপ্টের ফোল্ডারেই থাকলে
            os.path.join(os.getcwd(), path),   # বর্তমান টার্মিনাল ফোল্ডারে থাকলে
        ]
        found = next((p for p in candidates if os.path.isfile(p)), None)
        if not found:
            print("  ⚠ ফাইল পাওয়া যায়নি। নাম/পথ আবার দেখুন।")
            return None
        try:
            with open(found, "rb") as f:
                raw = f.read()
        except OSError as e:
            print(f"  ⚠ ফাইল পড়া যায়নি: {e}")
            return None
        name = os.path.basename(found)

    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        print("  ⚠ এটি টেক্সট ফাইল নয় (বা UTF-8 নয়)। ছবি/বাইনারি ফাইল যোগ করা যাবে না।")
        return None
    return text.replace("\r\n", "\n").rstrip("\n"), name


def read_pasted_code():
    print("কোড/টেক্সট পেস্ট করুন। শেষ করতে একটি আলাদা লাইনে শুধু END লিখুন।")
    lines = []
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line.strip() == "END":
            break
        lines.append(line)
    return "\n".join(lines).rstrip("\n")


def guess_language(filename):
    ext = os.path.splitext(filename)[1].lower()
    return EXT_LANG.get(ext, "Text")


# ---------------------------------------------------------------- commands --
def cmd_add():
    data = load_data()
    print("=" * 46)
    print("  CodeCraft — নতুন এন্ট্রি যোগ করুন")
    print("=" * 46)

    menu = choose_menu(data)
    title = ask("\nহেডলাইন (শিরোনাম)")
    description = ask_multiline("\nবিবরণ")

    print("\nফাইলের লিংক (https://…) লিখুন, অথবা ফাইল একই ফোল্ডারে থাকলে শুধু ফাইলের নাম লিখুন।")
    print("ফাইল ছাড়া শুধু কোড পেস্ট করতে চাইলে খালি রেখে Enter চাপুন।")
    code = filename = None
    while code is None:
        src = ask("ফাইল লিংক / ফাইলের নাম", required=False)
        if not src:
            code = read_pasted_code()
            if not code:
                print("  ⚠ কিছুই পেস্ট করা হয়নি।")
                code = None
                continue
            filename = ask("ফাইলের নাম (যেমন app.py, না থাকলে খালি রাখুন)", required=False)
            break
        result = read_source(src)
        if result:
            code, filename = result

    language = ask("ভাষা/লেবেল (HTML, JSON, Python, Node…)",
                   default=guess_language(filename or ""))

    item = {
        "id": f"{int(time.time())}-{len(data['items']) + 1}",
        "menu": menu,
        "title": title,
        "description": description,
        "language": language,
        "filename": filename or "",
        "code": code,
        "created": time.strftime("%Y-%m-%d"),
    }

    if menu not in data["menus"]:
        data["menus"].append(menu)
    data["items"].append(item)
    save_data(data)

    print("\n✔ যোগ হয়েছে!")
    print(f"  মেনু     : {menu}")
    print(f"  হেডলাইন  : {title}")
    print(f"  ভাষা     : {language}   ফাইল: {filename or '—'}   ({len(code.splitlines())} লাইন)")
    print("\nদেখতে চালান:  python add_codecraft.py serve")


def cmd_list():
    data = load_data()
    if not data["items"]:
        print("এখনও কোনো এন্ট্রি নেই।")
        return
    for i, it in enumerate(data["items"], 1):
        print(f"{i:>3}. [{it['menu']}] {it['title']}  ({it.get('language', '')} {it.get('filename', '')})")


def cmd_delete():
    data = load_data()
    if not data["items"]:
        print("মোছার মতো কোনো এন্ট্রি নেই।")
        return
    cmd_list()
    raw = ask("\nকোন নম্বরটি মুছবেন? (বাতিল করতে খালি রাখুন)", required=False)
    if not raw.isdigit() or not (1 <= int(raw) <= len(data["items"])):
        print("বাতিল করা হলো।")
        return
    it = data["items"][int(raw) - 1]
    if ask(f"“{it['title']}” মুছে ফেলবেন? (y/n)", default="n").lower() != "y":
        print("বাতিল করা হলো।")
        return
    data["items"].pop(int(raw) - 1)
    save_data(data)
    print("✔ মুছে ফেলা হয়েছে।")


def cmd_serve(port):
    import functools
    import http.server
    import socketserver
    import webbrowser

    handler = functools.partial(http.server.SimpleHTTPRequestHandler, directory=BASE_DIR)
    socketserver.TCPServer.allow_reuse_address = True
    try:
        with socketserver.TCPServer(("127.0.0.1", port), handler) as httpd:
            url = f"http://localhost:{port}/index.html"
            print(f"CodeCraft চালু: {url}   (বন্ধ করতে Ctrl+C)")
            try:
                webbrowser.open(url)
            except Exception:
                pass
            httpd.serve_forever()
    except OSError as e:
        print(f"সার্ভার চালু করা যায়নি: {e}\nঅন্য পোর্ট দিন, যেমন: python add_codecraft.py serve 9000")
    except KeyboardInterrupt:
        print("\nসার্ভার বন্ধ করা হলো।")


def main():
    args = sys.argv[1:]
    cmd = args[0].lower() if args else "add"
    try:
        if cmd == "add":
            cmd_add()
        elif cmd == "list":
            cmd_list()
        elif cmd == "delete":
            cmd_delete()
        elif cmd == "serve":
            cmd_serve(int(args[1]) if len(args) > 1 and args[1].isdigit() else 8000)
        else:
            print(__doc__)
    except KeyboardInterrupt:
        print("\nবাতিল করা হলো।")


if __name__ == "__main__":
