    a.href = item.href;
    socialWrap.appendChild(a);
  });
}

async function init() {
  const data = await loadData();
  if (!data) return;

  renderTopbar(data);
  renderHeader(data);
  renderHero(data);
  renderStats(data);
  renderModules(data);
  renderHierarchy(data);
  renderRolePanels(data);
  renderTestimonials(data);
  renderCta(data);
  renderContact(data);
  renderSitemap(data);
  renderFooter(data);
}

document.addEventListener("DOMContentLoaded", init);

