(function () {
  // Reveal on scroll
  const reveals = Array.from(document.querySelectorAll('.reveal'));
  if (!reveals.length) return;

  const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReduced) {
    reveals.forEach(el => el.classList.add('in-view'));
    return;
  }

  if ('IntersectionObserver' in window) {
    const obs = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('in-view');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12 });
    reveals.forEach(el => obs.observe(el));
  } else {
    reveals.forEach(el => el.classList.add('in-view'));
  }

  // Subtle parallax for background image (pointer + scroll)
  const bg = document.querySelector('.mission-hero__bg');
  if (!bg) return;
  let px = 0, py = 0, tx = 0, ty = 0;
  const damp = 0.06;

  function rafLoop() {
    tx += (px - tx) * damp;
    ty += (py - ty) * damp;
    bg.style.transform = `translate3d(${tx}px, ${ty}px, 0) scale(1.03)`;
    requestAnimationFrame(rafLoop);
  }
  requestAnimationFrame(rafLoop);

  window.addEventListener('pointermove', (e) => {
    const w = window.innerWidth, h = window.innerHeight;
    px = (e.clientX / w - 0.5) * 28; // range +/-14px
    py = (e.clientY / h - 0.5) * 18; // range +/-9px
  }, { passive: true });

  window.addEventListener('scroll', () => {
    const s = window.scrollY || window.pageYOffset;
    py = Math.max(-18, Math.min(18, (s / 200) * -6));
  }, { passive: true });

  // Respect reduced motion: disable transforms
  if (prefersReduced) {
    bg.style.transform = 'none';
  }
})();

// js/section/script.js
// Reveal animations and mission background progressive clarity
(function () {
  // Reveal on scroll
  const reveals = Array.from(document.querySelectorAll('.reveal'));
  const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReduced) {
    reveals.forEach(el => el.classList.add('in-view'));
  } else if ('IntersectionObserver' in window) {
    const obs = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('in-view');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12 });
    reveals.forEach(el => obs.observe(el));
  } else {
    reveals.forEach(el => el.classList.add('in-view'));
  }

  // Mission background progressive clarity
  const missionSection = document.getElementById('mission');
  const missionBg = document.getElementById('missionBg');
  if (missionSection && missionBg && !prefersReduced) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) missionSection.classList.add('in-view');
        else missionSection.classList.remove('in-view');
      });
    }, { threshold: [0.15, 0.45, 0.75] });
    observer.observe(missionSection);

    let ticking = false;
    window.addEventListener('scroll', () => {
      if (!missionSection.classList.contains('in-view')) return;
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        const rect = missionSection.getBoundingClientRect();
        const vh = window.innerHeight || document.documentElement.clientHeight;
        const progress = Math.min(1, Math.max(0, (vh - rect.top) / (vh + rect.height)));
        const blurStart = 18;
        const blurEnd = 4;
        const opacityStart = 0.28;
        const opacityEnd = 0.72;
        const blur = blurStart + (blurEnd - blurStart) * progress;
        const opacity = opacityStart + (opacityEnd - opacityStart) * progress;
        missionBg.style.filter = `blur(${blur}px) saturate(${0.9 + 0.15 * progress}) contrast(${0.9 + 0.12 * progress})`;
        missionBg.style.opacity = `${opacity}`;
        ticking = false;
      });
    }, { passive: true });
  }
})();

// js/script.js
// Search, counts, accessibility helpers, and footer year

document.addEventListener("DOMContentLoaded", () => {
  const searchInput = document.getElementById("searchInput");
  const pageItems = Array.from(document.querySelectorAll(".page-item"));
  const totalPagesEl = document.getElementById("totalPages");
  const mainSectionsEl = document.getElementById("mainSections");
  const currentYearEl = document.getElementById("current-year");

  // Set footer year
  if (currentYearEl) currentYearEl.textContent = new Date().getFullYear();

  // Compute and display counts
  function updateCounts() {
    const visibleItems = pageItems.filter(item => item.style.display !== "none");
    totalPagesEl.textContent = visibleItems.length;
    const sections = document.querySelectorAll(".section");
    mainSectionsEl.textContent = sections.length;
    // Update per-section counts (optional)
    sections.forEach(section => {
      const countEl = section.querySelector(".section-count");
      if (countEl) {
        const items = section.querySelectorAll(".page-item");
        countEl.textContent = items.length + (items.length === 1 ? " page" : " pages");
      }
    });
  }

  // Initial counts
  updateCounts();

  // Search filter
  if (searchInput) {
    searchInput.addEventListener("input", () => {
      const q = searchInput.value.trim().toLowerCase();
      pageItems.forEach(item => {
        const title = (item.getAttribute("data-title") || item.querySelector(".page-link")?.textContent || "").toLowerCase();
        const desc = (item.querySelector(".page-desc")?.textContent || "").toLowerCase();
        const matches = q === "" || title.includes(q) || desc.includes(q);
        item.style.display = matches ? "" : "none";
      });
      updateCounts();
    });

    // keyboard: press "/" to focus search
    document.addEventListener("keydown", (e) => {
      if (e.key === "/" && document.activeElement !== searchInput) {
        const tag = document.activeElement.tagName.toLowerCase();
        if (tag !== "input" && tag !== "textarea") {
          e.preventDefault();
          searchInput.focus();
        }
      }
    });
  }

  // Improve link focus visibility for keyboard users
  document.querySelectorAll("a").forEach(a => {
    a.addEventListener("focus", () => a.classList.add("focused"));
    a.addEventListener("blur", () => a.classList.remove("focused"));
  });

  // Ensure external links open safely
  document.querySelectorAll('a[target="_blank"]').forEach(a => {
    if (!a.getAttribute("rel")) a.setAttribute("rel", "noopener noreferrer");
  });
});

