      const R = (el) => { el.classList.add('reveal'); el.style.setProperty('--i', i++); return el; };
      const row = (dt, dd) => [h('dt', {}, dt), h('dd', {}, dd)];


      if (C.invocation) paper.append(R(h('p', { class: 'invocation', lang: 'ar', dir: 'rtl' }, C.invocation)));


