const fs = require('fs');
const path = require('path');

// Resolve file path
const filePath = path.resolve(__dirname, "quraner-fariwala.json");

// Read file as raw string
let raw = fs.readFileSync(filePath, "utf-8");

// Trim whitespace
raw = raw.trim();

// Remove BOM if exists
if (raw.charCodeAt(0) === 0xFEFF) {
  raw = raw.slice(1);
}

// Parse JSON safely
const data = JSON.parse(raw);

// Save pretty JSON
const outputPath = path.resolve(__dirname, "quraner-fariwala-copy.json");
fs.writeFileSync(outputPath, JSON.stringify(data, null, 2), "utf-8");

console.log("✅ JSON reformatted and saved as quraner-fariwala-copy.json");

// Set current year in footer
document.addEventListener('DOMContentLoaded', function () {
  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function (anchor) {
    anchor.addEventListener('click', function (e) {
      const href = this.getAttribute('href');
      if (href === '#' || href === '#top') {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
        return;
      }
      const target = document.querySelector(href);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });

  // Lazy load images using IntersectionObserver
  const images = document.querySelectorAll('img');
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries, obs) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = entry.target;
          // If you want to use data-src for lazy loading, swap src here
          // img.src = img.dataset.src;
          obs.unobserve(img);
        }
      });
    }, { rootMargin: '100px' });

    images.forEach(img => io.observe(img));
  }

  // Simple keyboard accessibility for video iframe
  const iframe = document.querySelector('.video-wrapper iframe');
  if (iframe) {
    iframe.setAttribute('tabindex', '0');
  }
});

:root{
  --primary:#004d40;
  --primary-foreground:#ffffff;
  --muted:#6b7280;
  --accent:#0ea5a4;
  --bg:#ffffff;
  --card:#fafafa;
  --radius:12px;
  --container-width:1200px;
  --max-width:1100px;
  --gap:1.25rem;
  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
  color-scheme: light;
}

*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{background:var(--bg);color:#111;line-height:1.5;-webkit-font-smoothing:antialiased}
.container{max-width:var(--container-width);margin:0 auto;padding:0 1rem}
.text-center{text-align:center}
.lead{font-size:1.05rem;color:var(--primary-foreground);opacity:.95;max-width:900px;margin:0.75rem auto}
.muted{color:var(--muted);margin-top:.5rem}

/* Hero */
.hero{background:var(--primary);color:var(--primary-foreground);padding:3.5rem 0}
.hero h1{font-size:2.25rem;line-height:1.05}
.hero .lead{color:rgba(255,255,255,0.9)}

/* Video */
.video-section{padding:3rem 0;text-align:center}
.video-wrapper{max-width:900px;margin:1.25rem auto;border-radius:12px;overflow:hidden;box-shadow:0 6px 18px rgba(2,6,23,0.08)}
.video-wrapper iframe{width:100%;height:520px;border:0;display:block}

/* Steps */
.steps-section{padding:3rem 0;background:linear-gradient(180deg,#fff 0%, #fbfbfb 100%)}
.steps-section h2{font-size:1.5rem}
.steps{margin-top:1.5rem;display:flex;flex-direction:column;gap:2.5rem}
.step{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;align-items:center}
.step.reverse{direction:ltr}
.step.reverse .step-content{order:2}
.step.reverse .step-media{order:1}
.step-content{padding:1rem}
.step-meta{display:flex;align-items:center;gap:.75rem}
.step-icon{width:44px;height:44px;border-radius:999px;background:var(--primary);color:var(--primary-foreground);display:flex;align-items:center;justify-content:center;font-weight:700}
.step h3{font-size:1.125rem;margin-top:.5rem}
.step p{color:#333;margin-top:.5rem}
.step ul{margin-top:.75rem;list-style:none;padding-left:0;display:grid;gap:.4rem}
.step ul li{position:relative;padding-left:1.6rem;color:var(--muted)}
.step ul li::before{content:"";position:absolute;left:0;top:.25rem;width:10px;height:10px;background:var(--accent);border-radius:2px}

/* Media */
.step-media img{width:100%;height:100%;object-fit:cover;border-radius:var(--radius);display:block;box-shadow:0 8px 20px rgba(2,6,23,0.06)}

/* Specs */
.specs{padding:2.5rem 0}
.spec-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem;margin-top:1rem}
.spec-card{background:var(--card);padding:1rem;border-radius:10px;text-align:center;box-shadow:0 4px 12px rgba(2,6,23,0.04)}
.spec-label{color:var(--muted);font-size:.95rem}
.spec-value{font-weight:700;margin-top:.4rem}

/* CTA */
.hero-cta{background:var(--primary);color:var(--primary-foreground);padding:2.5rem 0;margin-top:1.5rem}
.cta-buttons{display:flex;gap:1rem;justify-content:center;margin-top:1rem;flex-wrap:wrap}
.btn{display:inline-block;padding:.75rem 1.25rem;border-radius:8px;text-decoration:none;font-weight:600}
.btn.primary{background:var(--primary-foreground);color:var(--primary);box-shadow:0 6px 18px rgba(2,6,23,0.06)}
.btn.outline{background:transparent;border:2px solid rgba(255,255,255,0.18);color:var(--primary-foreground)}

/* Footer */
.site-footer{padding:1.5rem 0;text-align:center;color:var(--muted);font-size:.95rem}

/* Responsive */
@media (max-width:900px){
  .video-wrapper iframe{height:320px}
  .step{grid-template-columns:1fr;gap:1rem}
  .step.reverse .step-content{order:1}
  .step.reverse .step-media{order:2}
  .hero h1{font-size:1.75rem}
}

