* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background: linear-gradient(135deg, #07131f 0%, #0a1821 45%, #0b1f2d 100%);
  color: var(--text);
  font-family: "Inter", "Noto Sans Bengali", sans-serif;
}

body {
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
}

a { text-decoration: none; }

.splash-shell {
