.btn-secondary:hover {
  border-color: rgba(71, 215, 179, 0.5);
  background: rgba(71, 215, 179, 0.06);
}

.hero-graphic {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-graphic img {
