  filter: drop-shadow(0 25px 50px rgba(71, 215, 179, 0.14));
}

.feature-grid {
  position: relative;
  z-index: 1;
  width: min(1200px, 100%);
  margin: 24px auto 18px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.feature-card {
  background: rgba(15, 29, 41, 0.7);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 24px 20px;
  box-shadow: var(--shadow);
  transition: transform 0.25s ease, border-color 0.25s ease;
}

.feature-card:hover {
  border-color: rgba(71, 215, 179, 0.5);
  transform: translateY(-4px);
}

.feature-icon {
  font-size: 2rem;
  margin-bottom: 12px;
}

.feature-card h3 {
  margin: 0 0 10px;
  font-size: 1.1rem;
  color: var(--primary);
}

.feature-card p {
  margin: 0;
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--muted);
}

.splash-footer {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 18px 28px;
  margin-top: 22px;
  color: var(--muted);
  font-size: 0.82rem;
}

.splash-footer a {
  color: var(--primary);
  transition: 0.2s ease;
}

.splash-footer a:hover {
  color: var(--secondary);
}

@media (max-width: 980px) {
  .hero-panel {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .subtitle, .hero-text h2 {
    margin-left: auto;
    margin-right: auto;
  }

  .cta-row {
    justify-content: center;
  }

  .feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .splash-shell {
    padding-left: 16px;
    padding-right: 16px;
  }

  .feature-grid {
    grid-template-columns: 1fr;
  }

  .cta-row .btn {
    width: 100%;
  }

  .hero-text h2 {
    font-size: 2.3rem;
  }
}
