  font-size: clamp(1.8rem, 2.5vw, 2.5rem);
  margin-bottom: 6px;
}

.stat-card small {
  color: var(--muted);
}

.content-grid,
.bottom-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 18px;
}

.panel {
  background: rgba(15, 29, 41, 0.8);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 20px 18px;
  box-shadow: var(--shadow);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.panel-head h3 {
  margin: 0;
  font-size: 1.1rem;
}

.badge {
  display: inline-block;
  background: rgba(121, 183, 255, 0.12);
  color: var(--secondary);
  border: 1px solid rgba(121, 183, 255, 0.2);
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 700;
}

.badge.live {
  background: rgba(115, 224, 169, 0.12);
  color: var(--success);
  border-color: rgba(115, 224, 169, 0.2);
}

.tree-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.tree-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 10px;
  border-radius: 12px;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(71, 215, 179, 0.08);
}

.tree-level {
  color: var(--muted);
  font-size: 0.9rem;
}

.layer-list, .policy-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.layer-list li, .policy-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 10px;
  border-radius: 12px;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(71, 215, 179, 0.08);
  color: var(--text);
}

.layer-list em {
  color: var(--muted);
  font-style: normal;
  font-size: 0.82rem;
}

.role-stack {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.role-node {
  padding: 10px 12px;
  border-radius: 999px;
  background: rgba(71, 215, 179, 0.08);
  border: 1px solid rgba(71, 215, 179, 0.2);
  color: var(--primary);
  font-size: 0.82rem;
  font-weight: 700;
}

.site-footer {
  height: 52px;
  border-top: 1px solid var(--line);
  background: rgba(8, 18, 28, 0.8);
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 24px;
  color: var(--muted);
  font-size: 0.82rem;
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    border-right: none;
    border-bottom: 1px solid var(--line);
  }

  .stats-grid,
  .content-grid,
  .bottom-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .stats-grid,
  .content-grid,
  .bottom-grid {
    grid-template-columns: 1fr;
  }

  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }

  .footer-inner {
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    height: auto;
    padding-top: 12px;
    padding-bottom: 12px;
  }
}
